(389, 'develobeautia_studio_settings', 'a:3:{s:6:\"slides\";a:4:{i:0;a:8:{s:7:\"eyebrow\";s:26:\"DEVELOBEAUTIA · YOUR CITY\";s:5:\"title\";s:39:\"زیبایی تو، امضای توست\";s:11:\"description\";s:160:\"رنگ و لایت حرفه‌ای، میکاپ و خدمات زیبایی در فضایی آرام و دقیق؛ با انتخاب مدل پیش از رزرو.\";s:13:\"primary_label\";s:30:\"رزرو آنلاین نوبت\";s:15:\"secondary_label\";s:32:\"دیدن نمونه‌کارها\";s:8:\"position\";s:10:\"center 34%\";s:5:\"image\";s:99:\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe/assets/images/balayage-warm.jpg\";s:5:\"video\";s:86:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\";}i:1;a:8:{s:7:\"eyebrow\";s:24:\"MAKEUP · SIGNATURE LOOK\";s:5:\"title\";s:53:\"میکاپی که، شبیه خودت می‌ماند\";s:11:\"description\";s:171:\"نمونه‌کارهای واقعی دولوبیوتیا را ببین، سبک دلخواهت را انتخاب کن و برای مشاوره تخصصی وقت بگیر.\";s:13:\"primary_label\";s:19:\"انتخاب مدل\";s:15:\"secondary_label\";s:21:\"خدمات میکاپ\";s:8:\"position\";s:10:\"center 34%\";s:5:\"image\";s:92:\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe/assets/images/makeup.jpg\";s:5:\"video\";s:86:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\";}i:2;a:8:{s:7:\"eyebrow\";s:20:\"COLOR · CUT · CARE\";s:5:\"title\";s:58:\"رنگی هماهنگ با، پوست و استایل تو\";s:11:\"description\";s:102:\"مشاوره رنگ، انتخاب تناژ و اجرای ظریف با توجه به سلامت مو.\";s:13:\"primary_label\";s:28:\"رزرو مشاوره رنگ\";s:15:\"secondary_label\";s:26:\"دیدن نتیجه‌ها\";s:8:\"position\";s:10:\"center 34%\";s:5:\"image\";s:103:\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe/assets/images/caramel-highlight.jpg\";s:5:\"video\";s:87:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\";}i:3;a:8:{s:7:\"eyebrow\";s:29:\"DEVELOBEAUTIA · MAKEUP REELS\";s:5:\"title\";s:53:\"فینیشی تمیز برای لحظه‌های تو\";s:11:\"description\";s:121:\"نتیجه واقعی را ببین، مدل را انتخاب کن و با آرامش برای نوبت اقدام کن.\";s:13:\"primary_label\";s:19:\"انتخاب مدل\";s:15:\"secondary_label\";s:32:\"دیدن نمونه‌کارها\";s:8:\"position\";s:10:\"center 34%\";s:5:\"image\";s:92:\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe/assets/images/makeup.jpg\";s:5:\"video\";s:85:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\";}}s:8:\"magazine\";a:25:{s:15:\"section_eyebrow\";s:24:\"DEVELOBEAUTIA / THE EDIT\";s:13:\"section_title\";s:44:\"مجلهٔ زیبایی دولوبیوتیا\";s:19:\"section_description\";s:127:\"یک انتخاب آرام و دقیق؛ صفحه‌ها را ورق بزن و مسیر مناسب خودت را پیدا کن.\";s:13:\"cover_eyebrow\";s:26:\"DEVELOBEAUTIA · YOUR CITY\";s:11:\"cover_title\";s:36:\"زیبایی، انتخاب توست\";s:17:\"cover_description\";s:140:\"انتخاب‌های دقیق برای مو، میکاپ و استایل؛ در یک شمارهٔ اختصاصی از دولوبیوتیا.\";s:11:\"cover_issue\";s:14:\"VOL. 01 / 2026\";s:11:\"cover_image\";s:81:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\";s:14:\"opener_eyebrow\";s:25:\"LETTER FROM DEVELOBEAUTIA\";s:12:\"opener_title\";s:46:\"برای انتخابی که شبیه توست\";s:18:\"opener_description\";s:233:\"این شماره را برای لحظه‌ای ساخته‌ایم که می‌خواهی با خیال راحت انتخاب کنی؛ تصویر را ببین، جزئیات را بخوان و برای مشاوره آماده شو.\";s:12:\"opener_quote\";s:94:\"زیبایی، وقتی ماندگار می‌شود که با خودت هماهنگ باشد.\";s:16:\"contents_eyebrow\";s:13:\"IN THIS ISSUE\";s:14:\"contents_title\";s:30:\"فهرست انتخاب‌ها\";s:20:\"contents_description\";s:150:\"چهار مسیر اصلی دولوبیوتیا را در این شماره ببین و مستقیم به صفحهٔ خدمت موردنظرت برو.\";s:15:\"closing_eyebrow\";s:25:\"DEVELOBEAUTIA / LAST PAGE\";s:13:\"closing_title\";s:52:\"برای انتخابت وقت مشاوره بگیر\";s:19:\"closing_description\";s:121:\"اگر هنوز مرددی، پذیرش دولوبیوتیا برای انتخاب مسیر مناسب کنارت است.\";s:14:\"closing_button\";s:17:\"شروع رزرو\";s:13:\"closing_image\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\";s:12:\"accent_color\";s:7:\"#b45a6e\";s:9:\"ink_color\";s:7:\"#492534\";s:11:\"paper_color\";s:7:\"#f8eee9\";s:13:\"sound_enabled\";s:1:\"1\";s:5:\"pages\";a:4:{i:0;a:7:{s:7:\"eyebrow\";s:26:\"01 / DEVELOBEAUTIA SERVICE\";s:5:\"title\";s:18:\"رنگ و لایت\";s:11:\"description\";s:134:\"بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.\";s:5:\"image\";s:82:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\";s:7:\"service\";s:18:\"رنگ و لایت\";s:12:\"button_label\";s:24:\"رزرو این خدمت\";s:7:\"enabled\";s:1:\"1\";}i:1;a:7:{s:7:\"eyebrow\";s:26:\"02 / DEVELOBEAUTIA SERVICE\";s:5:\"title\";s:22:\"میکاپ و عروس\";s:11:\"description\";s:92:\"طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.\";s:5:\"image\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\";s:7:\"service\";s:22:\"میکاپ و عروس\";s:12:\"button_label\";s:24:\"رزرو این خدمت\";s:7:\"enabled\";s:1:\"1\";}i:2;a:7:{s:7:\"eyebrow\";s:26:\"03 / DEVELOBEAUTIA SERVICE\";s:5:\"title\";s:19:\"خدمات ناخن\";s:11:\"description\";s:74:\"کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.\";s:5:\"image\";s:81:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\";s:7:\"service\";s:19:\"خدمات ناخن\";s:12:\"button_label\";s:24:\"رزرو این خدمت\";s:7:\"enabled\";s:1:\"1\";}i:3;a:7:{s:7:\"eyebrow\";s:26:\"04 / DEVELOBEAUTIA SERVICE\";s:5:\"title\";s:16:\"مو و ابرو\";s:11:\"description\";s:92:\"هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.\";s:5:\"image\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\";s:7:\"service\";s:16:\"مو و ابرو\";s:12:\"button_label\";s:24:\"رزرو این خدمت\";s:7:\"enabled\";s:1:\"1\";}}}s:8:\"brochure\";a:5:{s:7:\"eyebrow\";s:26:\"DEVELOBEAUTIA · YOUR CITY\";s:5:\"title\";s:46:\"نمونه‌کارهای دولوبیوتیا\";s:11:\"description\";s:132:\"آرشیو واقعی تصاویر و ویدیوهای دولوبیوتیا برای انتخاب مدل و رزرو آگاهانه.\";s:13:\"closing_title\";s:52:\"برای انتخابت وقت مشاوره بگیر\";s:19:\"closing_description\";s:121:\"اگر هنوز مرددی، پذیرش دولوبیوتیا برای انتخاب مسیر مناسب کنارت است.\";}}', 'off'),
