(558, 'develobeautia_atelier_catalogue', 'a:6:{s:5:\"paper\";s:7:\"#fff6ec\";s:6:\"accent\";s:7:\"#986d4d\";s:4:\"logo\";s:114:\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe/assets/images/develobeautia-mirror-logo-v3.png\";s:10:\"background\";s:0:\"\";s:5:\"sound\";s:0:\"\";s:5:\"items\";a:6:{i:0;a:7:{s:2:\"id\";s:15:\"develobeautia-1\";s:5:\"title\";s:35:\"بلوند صدفی موج‌دار\";s:7:\"service\";s:18:\"رنگ و لایت\";s:11:\"description\";s:146:\"موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.\";s:4:\"note\";s:0:\"\";s:5:\"align\";s:5:\"right\";s:6:\"images\";a:1:{i:0;s:55:\"http://localhost/develobeautia/photos/1790196088279.jpg\";}}i:1;a:7:{s:2:\"id\";s:15:\"develobeautia-2\";s:5:\"title\";s:17:\"باب بلوند\";s:7:\"service\";s:16:\"مو و ابرو\";s:11:\"description\";s:67:\"فرم کوتاه و منظم با قاب روشن دور صورت.\";s:4:\"note\";s:0:\"\";s:5:\"align\";s:5:\"right\";s:6:\"images\";a:1:{i:0;s:55:\"http://localhost/develobeautia/photos/1790196088290.jpg\";}}i:2;a:7:{s:2:\"id\";s:15:\"develobeautia-3\";s:5:\"title\";s:21:\"موج کاراملی\";s:7:\"service\";s:18:\"رنگ و لایت\";s:11:\"description\";s:75:\"تناژ گرم کاراملی با موج‌های نرم و درخشان.\";s:4:\"note\";s:0:\"\";s:5:\"align\";s:5:\"right\";s:6:\"images\";a:1:{i:0;s:55:\"http://localhost/develobeautia/photos/1790196094108.jpg\";}}i:3;a:7:{s:2:\"id\";s:15:\"develobeautia-4\";s:5:\"title\";s:19:\"میکاپ لایت\";s:7:\"service\";s:22:\"میکاپ و عروس\";s:11:\"description\";s:61:\"آرایش ظریف چشم و فینیش طبیعی پوست.\";s:4:\"note\";s:0:\"\";s:5:\"align\";s:5:\"right\";s:6:\"images\";a:1:{i:0;s:55:\"http://localhost/develobeautia/photos/1790196832316.jpg\";}}i:4;a:7:{s:2:\"id\";s:15:\"develobeautia-5\";s:5:\"title\";s:19:\"بلوند بلند\";s:7:\"service\";s:18:\"رنگ و لایت\";s:11:\"description\";s:58:\"ترکیب لایت روشن با فرم و حالت مو.\";s:4:\"note\";s:0:\"\";s:5:\"align\";s:5:\"right\";s:6:\"images\";a:1:{i:0;s:55:\"http://localhost/develobeautia/photos/1790196092137.jpg\";}}i:5;a:7:{s:2:\"id\";s:15:\"develobeautia-6\";s:5:\"title\";s:22:\"باب نقره‌ای\";s:7:\"service\";s:16:\"مو و ابرو\";s:11:\"description\";s:55:\"کوتاهی منظم با تناژ سرد و روشن.\";s:4:\"note\";s:0:\"\";s:5:\"align\";s:5:\"right\";s:6:\"images\";a:1:{i:0;s:55:\"http://localhost/develobeautia/photos/1790196088272.jpg\";}}}}', 'off'),
