(1593, 'wpcode_snippets', 'a:1:{s:10:\"everywhere\";a:7:{i:0;a:14:{s:2:\"id\";i:337;s:5:\"title\";s:39:\"DeveloBeautia Elementor Section Widgets\";s:4:\"code\";s:25358:\"add_action( \'elementor/widgets/register\', static function ( $manager ) {\r\n    if ( ! class_exists( \'\\Elementor\\Widget_Base\' ) || class_exists( \'DeveloBeautia_Elementor_Section_Widget_Base\', false ) ) return;\r\n    abstract class DeveloBeautia_Elementor_Section_Widget_Base extends \\Elementor\\Widget_Base {\r\n        public function get_categories(): array { return array( \'develobeautia\' ); }\r\n        public function get_icon(): string { return \'eicon-apps\'; }\r\n        protected function add_title_control( string $default ): void {\r\n            $this->start_controls_section( \'content\', array( \'label\' => \'محتوا\' ) );\r\n            $this->add_control( \'title\', array( \'label\' => \'عنوان بخش\', \'type\' => \\Elementor\\Controls_Manager::TEXT, \'default\' => $default, \'label_block\' => true ) );\r\n        }\r\n        protected function add_count_control( int $default, int $max ): void {\r\n            $this->add_control( \'count\', array( \'label\' => \'تعداد موارد\', \'type\' => \\Elementor\\Controls_Manager::NUMBER, \'default\' => $default, \'min\' => 1, \'max\' => $max ) );\r\n            $this->end_controls_section();\r\n        }\r\n        protected function render_heading( string $title ): void {\r\n            if ( \'\' !== trim( $title ) ) echo \'<header class=\"section-heading compact\"><h2>\' . esc_html( $title ) . \'</h2></header>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Slider_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_slider\'; }\r\n        public function get_title(): string { return \'اسلایدر صفحه اصلی دولوبیوتیا\'; }\r\n        protected function render(): void {\r\n            echo \'<div class=\"develobeautia-elementor-section develobeautia-elementor-slider\">\';\r\n            if ( function_exists( \'develobeautia_dynamic_slider_render\' ) ) develobeautia_dynamic_slider_render();\r\n            else echo \'<p>اسلایدر دولوبیوتیا در این صفحه در دسترس نیست.</p>\';\r\n            echo \'</div>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Portfolio_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_portfolio\'; }\r\n        public function get_title(): string { return \'نمونه‌کارهای دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'نمونه‌کارهای دولوبیوتیا\' ); $this->add_count_control( 6, 24 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 24, absint( $settings[\'count\'] ?? 6 ) ) );\r\n            $items = function_exists( \'develobeautia_server_works\' ) ? array_slice( (array) develobeautia_server_works(), 0, $limit ) : array();\r\n            echo \'<section class=\"develobeautia-elementor-section develobeautia-elementor-portfolio\">\';\r\n            $this->render_heading( (string) ( $settings[\'title\'] ?? \'\' ) );\r\n            if ( empty( $items ) ) { echo \'<p>هنوز نمونه‌کاری برای نمایش وجود ندارد.</p></section>\'; return; }\r\n            echo \'<div class=\"develobeautia-elementor-media-grid\">\';\r\n            foreach ( $items as $item ) {\r\n                $item = (array) $item; $url = $item[\'url\'] ?? ( $item[\'image\'] ?? \'\' );\r\n                if ( \'\' === $url ) continue;\r\n                $title = $item[\'title\'] ?? \'نمونه‌کار دولوبیوتیا\'; $label = $item[\'label\'] ?? \'\';\r\n                echo \'<article class=\"develobeautia-elementor-media-card\"><a href=\"\' . esc_url( $url ) . \'\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"\' . esc_url( $url ) . \'\" alt=\"\' . esc_attr( $title ) . \'\"><span class=\"develobeautia-elementor-card-copy\">\';\r\n                if ( \'\' !== $label ) echo \'<small>\' . esc_html( $label ) . \'</small>\';\r\n                echo \'<strong>\' . esc_html( $title ) . \'</strong></span></a></article>\';\r\n            }\r\n            echo \'</div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Videos_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_videos\'; }\r\n        public function get_title(): string { return \'ویدیوهای دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'نتیجه‌ها در حرکت\' ); $this->add_count_control( 4, 17 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 17, absint( $settings[\'count\'] ?? 4 ) ) );\r\n            $items = function_exists( \'develobeautia_server_videos\' ) ? array_slice( (array) develobeautia_server_videos(), 0, $limit ) : array();\r\n            echo \'<section class=\"develobeautia-elementor-section develobeautia-elementor-videos work-showcase\"><div class=\"work-showcase__inner\">\';\r\n            $this->render_heading( (string) ( $settings[\'title\'] ?? \'\' ) );\r\n            if ( empty( $items ) ) { echo \'<p>هنوز ویدیویی برای نمایش وجود ندارد.</p></div></section>\'; return; }\r\n            echo \'<div class=\"video-grid work-showcase__videos\">\';\r\n            foreach ( $items as $item ) {\r\n                $item = (array) $item; $video = $item[\'video_file\'] ?? \'\'; $poster = $item[\'poster_url\'] ?? ( $item[\'poster\'] ?? \'\' );\r\n                if ( $video && preg_match( \'/(\\d{4})\\.mp4(?:\\?.*)?$/\', $video, $match ) ) $poster = home_url( \'/wp-content/uploads/2026/10/develobeautia-video-poster-\' . $match[1] . \'.webp\' );\r\n                $title = $item[\'title\'] ?? \'ویدیوی دولوبیوتیا\'; $label = $item[\'label\'] ?? \'\';\r\n                echo \'<article class=\"video-card local-video-card\"><div class=\"video-frame\" data-title=\"\' . esc_attr( $title ) . \'\" style=\"\' . esc_attr( \'--video-poster:url(&quot;\' . esc_url( $poster ) . \'&quot;)\' ) . \'\">\';\r\n                if ( $video ) echo \'<img class=\"video-poster-still\" loading=\"lazy\" src=\"\' . esc_url( $poster ) . \'\" alt=\"\' . esc_attr( $title . \'، کاور ویدیو\' ) . \'\"><video class=\"local-reel\" data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"\' . esc_url( $poster ) . \'\" data-src=\"\' . esc_url( $video ) . \'\"></video><button type=\"button\" class=\"play-mark video-toggle\" aria-label=\"پخش ویدیوی \' . esc_attr( $title ) . \'\">▶</button>\';\r\n                echo \'</div><div><small>\' . esc_html( $label ) . \'</small><h3>\' . esc_html( $title ) . \'</h3><div class=\"video-actions\"><button type=\"button\" class=\"text-button video-toggle\">پخش ویدیو ▶</button></div></div></article>\';\r\n            }\r\n            echo \'</div></div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Magazine_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_magazine\'; }\r\n        public function get_title(): string { return \'مجله تصویری دولوبیوتیا\'; }\r\n        protected function render(): void {\r\n            echo \'<div class=\"develobeautia-elementor-section develobeautia-elementor-magazine\">\';\r\n            if ( locate_template( \'template-parts/magazine.php\' ) ) get_template_part( \'template-parts/magazine\' );\r\n            else echo \'<p>قالب مجله تصویری در دسترس نیست.</p>\';\r\n            echo \'</div>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Articles_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_articles\'; }\r\n        public function get_title(): string { return \'مقاله‌های زیبایی‌نامه\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'تازه‌ترین از زیبایی‌نامه\' ); $this->add_count_control( 4, 12 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 12, absint( $settings[\'count\'] ?? 4 ) ) );\r\n            $posts = get_posts( array( \'post_type\' => \'post\', \'post_status\' => \'publish\', \'numberposts\' => $limit, \'orderby\' => \'date\', \'order\' => \'DESC\' ) );\r\n            echo \'<section class=\"develobeautia-elementor-section home-journal-preview section\"><div class=\"section-heading home-journal-heading\"><div><h2>\' . esc_html( (string) ( $settings[\'title\'] ?? \'\' ) ) . \'</h2></div><a class=\"text-button\" href=\"\' . esc_url( function_exists( \'develobeautia_page_url\' ) ? develobeautia_page_url( \'beauty-journal\', \'/beauty-journal/\' ) : home_url( \'/beauty-journal/\' ) ) . \'\">همه مقاله‌ها ←</a></div>\';\r\n            if ( empty( $posts ) ) { echo \'<p>هنوز مقاله‌ای منتشر نشده است.</p></section>\'; return; }\r\n            echo \'<div class=\"home-journal-grid\">\';\r\n            foreach ( $posts as $post ) {\r\n                $image = get_the_post_thumbnail_url( $post, \'large\' );\r\n                if ( ! $image && function_exists( \'develobeautia_asset\' ) ) $image = develobeautia_asset( \'makeup.jpg\' );\r\n                echo \'<article class=\"home-journal-card reveal\"><a class=\"home-journal-image\" href=\"\' . esc_url( get_permalink( $post ) ) . \'\"><img loading=\"lazy\" src=\"\' . esc_url( $image ) . \'\" alt=\"\' . esc_attr( get_the_title( $post ) ) . \'\"></a><div><small>\' . esc_html( get_the_date( \'j F Y\', $post ) ) . \'</small><h3><a href=\"\' . esc_url( get_permalink( $post ) ) . \'\">\' . esc_html( get_the_title( $post ) ) . \'</a></h3><p>\' . esc_html( wp_trim_words( wp_strip_all_tags( $post->post_content ), 24 ) ) . \'</p><a class=\"teaser-link\" href=\"\' . esc_url( get_permalink( $post ) ) . \'\">مطالعه مقاله ←</a></div></article>\';\r\n            }\r\n            echo \'</div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Contact_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_contact\'; }\r\n        public function get_title(): string { return \'اطلاعات تماس دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'تماس با دولوبیوتیا\' ); $this->end_controls_section(); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $option = static function ( $key, $fallback ) { return function_exists( \'develobeautia_option\' ) ? develobeautia_option( $key, $fallback ) : $fallback; };\r\n            $address = $option( \'address\', \'شهر شما، نشانی سالن شما\' );\r\n            $phone = $option( \'phone\', \'02100000000\' ); $mobile = $option( \'mobile\', \'09000000000\' ); $instagram = $option( \'instagram\', \'\' ); if ( ! $instagram ) $instagram = \'#\';\r\n            $phone_link = preg_replace( \'/[^0-9+]/\', \'\', $phone ); $mobile_link = preg_replace( \'/[^0-9+]/\', \'\', $mobile );\r\n            $instagram_url = $instagram;\r\n            if ( $instagram && ! preg_match( \'~^https?://~i\', $instagram ) ) $instagram_url = \'https://instagram.com/\' . ltrim( $instagram, \'@/ \' );\r\n            echo \'<section class=\"develobeautia-elementor-section develobeautia-elementor-contact section\"><div class=\"section-heading compact\"><h2>\' . esc_html( (string) ( $settings[\'title\'] ?? \'تماس با دولوبیوتیا\' ) ) . \'</h2><p>منتظر دیدنت هستیم</p></div><div class=\"develobeautia-elementor-contact-grid\"><div class=\"develobeautia-elementor-contact-address\"><span>آدرس سالن</span><p>\' . esc_html( $address ) . \'</p><a href=\"\' . esc_url( \'https://maps.google.com/?q=\' . rawurlencode( $address ) ) . \'\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a></div>\';\r\n            if ( $phone_link ) echo \'<a class=\"develobeautia-elementor-contact-item\" href=\"tel:\' . esc_attr( $phone_link ) . \'\"><small>تلفن سالن</small><strong>\' . esc_html( $phone ) . \'</strong></a>\';\r\n            if ( $mobile_link ) echo \'<a class=\"develobeautia-elementor-contact-item\" href=\"tel:\' . esc_attr( $mobile_link ) . \'\"><small>رزرو و مشاوره</small><strong>\' . esc_html( $mobile ) . \'</strong></a>\';\r\n            if ( $instagram_url ) echo \'<a class=\"develobeautia-elementor-contact-item\" href=\"\' . esc_url( $instagram_url ) . \'\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a>\';\r\n            echo \'</div><div class=\"develobeautia-elementor-contact-cta\"><button type=\"button\" class=\"button open-booking\">رزرو نوبت</button></div></section>\';\r\n        }\r\n    }\r\n    foreach ( array( \'DeveloBeautia_Elementor_Slider_Widget\', \'DeveloBeautia_Elementor_Portfolio_Widget\', \'DeveloBeautia_Elementor_Videos_Widget\', \'DeveloBeautia_Elementor_Magazine_Widget\', \'DeveloBeautia_Elementor_Articles_Widget\', \'DeveloBeautia_Elementor_Contact_Widget\' ) as $class ) {\r\n        $widget = new $class(); $registered = method_exists( $manager, \'get_widget_types\' ) ? $manager->get_widget_types() : array();\r\n        if ( ! isset( $registered[ $widget->get_name() ] ) ) $manager->register( $widget );\r\n    }\r\n}, 101 );\r\n\r\nadd_action( \'wp_enqueue_scripts\', static function () {\r\n    if ( is_admin() ) return;\r\n    $preview_id = isset( $_GET[\'elementor-preview\'] ) ? absint( wp_unslash( $_GET[\'elementor-preview\'] ) ) : 0;\r\n    $post_id = $preview_id ?: get_queried_object_id();\r\n    $elementor_data = $post_id ? get_post_meta( $post_id, \'_elementor_data\', true ) : \'\';\r\n    if ( ! is_string( $elementor_data ) ) $elementor_data = \'\';\r\n    $types = array( \'develobeautia_slider\', \'develobeautia_portfolio\', \'develobeautia_videos\', \'develobeautia_magazine\', \'develobeautia_articles\', \'develobeautia_contact\' );\r\n    $has_widget = $preview_id > 0;\r\n    foreach ( $types as $type ) if ( false !== strpos( $elementor_data, $type ) ) { $has_widget = true; break; }\r\n    if ( ! $has_widget ) return;\r\n    wp_register_style( \'develobeautia-elementor-section-widgets\', false, array(), \'1.0.0\' );\r\n    wp_enqueue_style( \'develobeautia-elementor-section-widgets\' );\r\n    wp_add_inline_style( \'develobeautia-elementor-section-widgets\', \'.develobeautia-elementor-section{direction:rtl;min-width:0;max-width:100%}.develobeautia-elementor-media-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.develobeautia-elementor-media-card{min-width:0;overflow:hidden;border:1px solid rgba(70,80,72,.12);border-radius:18px;background:#fff;box-shadow:0 12px 34px rgba(36,47,40,.08)}.develobeautia-elementor-media-card>a{display:block;height:100%;color:inherit;text-decoration:none}.develobeautia-elementor-media-card img{display:block;width:100%;aspect-ratio:4/5;object-fit:cover}.develobeautia-elementor-card-copy{display:grid;gap:7px;padding:14px 16px 18px}.develobeautia-elementor-card-copy small,.develobeautia-elementor-contact-item small{color:#778078;font-size:.76rem}.develobeautia-elementor-card-copy strong{font-size:1rem;line-height:1.6}.develobeautia-elementor-videos .video-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.develobeautia-elementor-videos .video-card{min-width:0}.develobeautia-elementor-videos video{width:100%;max-width:100%}.develobeautia-elementor-magazine{overflow:hidden}.develobeautia-elementor-contact-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:14px}.develobeautia-elementor-contact-address,.develobeautia-elementor-contact-item{display:grid;align-content:center;gap:8px;min-width:0;padding:20px;border:1px solid rgba(70,80,72,.12);border-radius:16px;background:#fff;color:inherit;text-decoration:none}.develobeautia-elementor-contact-address span{font-size:.8rem;color:#778078}.develobeautia-elementor-contact-address p{margin:0;line-height:1.8}.develobeautia-elementor-contact-address>a{color:inherit;text-decoration:underline;text-underline-offset:4px}.develobeautia-elementor-contact-item strong{overflow-wrap:anywhere}.develobeautia-elementor-contact-cta{margin-top:20px}@media(max-width:900px){.develobeautia-elementor-media-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.develobeautia-elementor-videos .video-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.develobeautia-elementor-contact-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.develobeautia-elementor-media-grid{gap:10px}.develobeautia-elementor-card-copy{padding:10px 11px 13px}.develobeautia-elementor-contact-grid{grid-template-columns:1fr}.develobeautia-elementor-contact-address,.develobeautia-elementor-contact-item{padding:15px}.develobeautia-elementor-videos .video-grid{gap:12px}}\' );\r\n    if ( ( $preview_id || false !== strpos( $elementor_data, \'develobeautia_magazine\' ) ) && function_exists( \'develobeautia_atelier_data\' ) && ! wp_script_is( \'develobeautia-atelier\', \'enqueued\' ) ) {\r\n        wp_enqueue_style( \'develobeautia-elementor-atelier\', get_theme_file_uri( \'assets/css/atelier.css\' ), array(), null );\r\n        wp_enqueue_script( \'develobeautia-elementor-atelier\', get_theme_file_uri( \'assets/js/atelier.js\' ), array(), null, true );\r\n        wp_localize_script( \'develobeautia-elementor-atelier\', \'DeveloBeautiaAtelier\', develobeautia_atelier_data() );\r\n    }\r\n}, 30 );\r\n\r\nadd_filter( \'template_include\', static function ( $template ) {\r\n    $preview_id = isset( $_GET[\'elementor-preview\'] ) ? absint( wp_unslash( $_GET[\'elementor-preview\'] ) ) : 0;\r\n    $is_develobeautia_home = is_front_page() && 100 === (int) get_queried_object_id();\r\n    if ( 100 === $preview_id || $is_develobeautia_home ) return get_theme_file_path( \'page.php\' );\r\n    return $template;\r\n}, 9999 );\r\n\r\nadd_action( \'wp_head\', static function () {\r\n    if ( is_page( 100 ) ) echo \'<style>body.page-id-100 #main{padding-top:40px!important}body.page-id-100 #main>article>h1{display:none!important}body.page-id-100 .mds-picture img{object-fit:cover!important}body.page-id-100 .mds-transition-fade .mds-slide{transition:opacity .9s ease,visibility 0s linear .9s!important}body.page-id-100 .mds-transition-fade .mds-slide.is-active{transition-delay:0s!important}</style>\';\r\n}, 99 );\r\n\r\nadd_action( \'elementor/widgets/register\', static function ( $manager ) {\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor_Section_Widget_Base\', false ) || class_exists( \'DeveloBeautia_Elementor_Trust_Widget\', false ) ) return;\r\n    final class DeveloBeautia_Elementor_Trust_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_trust\'; }\r\n        public function get_title(): string { return \'مزیت‌های تجربه دولوبیوتیا\'; }\r\n        protected function render(): void {\r\n            echo \'<section class=\"trust-strip trust-strip-pro develobeautia-elementor-section develobeautia-elementor-trust\" aria-label=\"مزیت‌های تجربه دولوبیوتیا\"><div><span>۰۱</span><strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small></div><div><span>۰۲</span><strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small></div><div><span>۰۳</span><strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small></div><div><span>۰۴</span><strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Before_After_Archive_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_before_after_archive\'; }\r\n        public function get_title(): string { return \'آرشیو قبل و بعد دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'قبل و بعد\' ); $this->add_count_control( 4, 4 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 4, absint( $settings[\'count\'] ?? 4 ) ) );\r\n            echo \'<section class=\"develobeautia-elementor-section work-showcase__group work-showcase__group--before-after\"><div class=\"work-showcase__label\"><span>01</span><div><h3>\' . esc_html( (string) ( $settings[\'title\'] ?? \'قبل و بعد\' ) ) . \'</h3><p>جزئیات هر تغییر را کنار هم ببین.</p></div></div>\';\r\n            if ( function_exists( \'develobeautia_before_after_grid\' ) ) echo develobeautia_before_after_grid( $limit );\r\n            echo \'</section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Booking_Steps_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_booking_steps\'; }\r\n        public function get_title(): string { return \'مراحل رزرو دولوبیوتیا\'; }\r\n        protected function register_controls(): void {\r\n            $this->add_title_control( \'BOOK NOW\' );\r\n            $this->add_control( \'button\', array( \'label\' => \'متن دکمه\', \'type\' => \\Elementor\\Controls_Manager::TEXT, \'default\' => \'همین حالا رزرو کن\', \'label_block\' => true ) );\r\n            $this->end_controls_section();\r\n        }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            echo \'<section class=\"process section develobeautia-elementor-section develobeautia-elementor-booking-steps\" id=\"booking\"><div class=\"section-heading section-heading--single\"><h2 class=\"section-title-only\">\' . esc_html( (string) ( $settings[\'title\'] ?? \'BOOK NOW\' ) ) . \'</h2></div><div class=\"steps\"><div><span>۱</span><strong>انتخاب خدمت</strong><small>خدمت و متخصص</small></div><div><span>۲</span><strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small></div><div><span>۳</span><strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small></div><div><span>۴</span><strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small></div></div><button type=\"button\" class=\"button open-booking\">\' . esc_html( (string) ( $settings[\'button\'] ?? \'همین حالا رزرو کن\' ) ) . \'</button></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Reviews_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_reviews\'; }\r\n        public function get_title(): string { return \'بازخوردهای دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'حس خوبِ اعتماد\' ); $this->add_count_control( 6, 12 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 12, absint( $settings[\'count\'] ?? 6 ) ) );\r\n            $posts = get_posts( array( \'post_type\' => \'develobeautia_review\', \'post_status\' => \'publish\', \'numberposts\' => $limit, \'orderby\' => \'menu_order\', \'order\' => \'ASC\' ) );\r\n            if ( empty( $posts ) ) return;\r\n            echo \'<section class=\"reviews section develobeautia-elementor-section develobeautia-elementor-reviews\"><div class=\"section-heading compact\"><span class=\"eyebrow\">از زبان همراهان دولوبیوتیا</span><h2>\' . esc_html( (string) ( $settings[\'title\'] ?? \'حس خوبِ اعتماد\' ) ) . \'</h2><p>بازخوردهای عمومی و مثبت منتشرشده در صفحه رسمی دولوبیوتیا.</p></div><div class=\"review-grid\">\';\r\n            foreach ( $posts as $review ) {\r\n                $name = get_post_meta( $review->ID, \'_develobeautia_reviewer\', true ) ?: \'همراه دولوبیوتیا\';\r\n                $source = get_post_meta( $review->ID, \'_develobeautia_review_source\', true ) ?: \'اینستاگرام دولوبیوتیا\';\r\n                echo \'<blockquote><span>“</span><p>\' . esc_html( wp_strip_all_tags( $review->post_content ) ) . \'</p><footer><strong>\' . esc_html( $name ) . \'</strong><small>\' . esc_html( $source ) . \'</small></footer></blockquote>\';\r\n            }\r\n            echo \'</div></section>\';\r\n        }\r\n    }\r\n    foreach ( array( \'DeveloBeautia_Elementor_Trust_Widget\', \'DeveloBeautia_Elementor_Before_After_Archive_Widget\', \'DeveloBeautia_Elementor_Booking_Steps_Widget\', \'DeveloBeautia_Elementor_Reviews_Widget\' ) as $class ) {\r\n        $widget = new $class(); $registered = method_exists( $manager, \'get_widget_types\' ) ? $manager->get_widget_types() : array();\r\n        if ( ! isset( $registered[ $widget->get_name() ] ) ) $manager->register( $widget );\r\n    }\r\n}, 102 );\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-04 01:04:42\";}i:1;a:14:{s:2:\"id\";i:333;s:5:\"title\";s:37:\"DeveloBeautia Elementor Widget Loader\";s:4:\"code\";s:2048:\"add_action( \'elementor/elements/categories_registered\', static function ( $manager ) {\r\n    if ( ! class_exists( \'\\Elementor\\Widget_Base\' ) ) {\r\n        return;\r\n    }\r\n    $base = defined( \'DEVELOBEAUTIA_SUITE_DIR\' ) ? DEVELOBEAUTIA_SUITE_DIR : WP_PLUGIN_DIR . \'/develobeautia-suite/\';\r\n    $file = $base . \'includes/class-elementor.php\';\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) && is_readable( $file ) ) {\r\n        require_once $file;\r\n    }\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) ) {\r\n        return;\r\n    }\r\n    $categories = method_exists( $manager, \'get_categories\' ) ? $manager->get_categories() : array();\r\n    if ( ! isset( $categories[\'develobeautia\'] ) ) {\r\n        DeveloBeautia_Elementor::category( $manager );\r\n    }\r\n}, 99 );\r\n\r\nadd_action( \'elementor/widgets/register\', static function ( $manager ) {\r\n    if ( ! class_exists( \'\\Elementor\\Widget_Base\' ) ) {\r\n        return;\r\n    }\r\n    $base = defined( \'DEVELOBEAUTIA_SUITE_DIR\' ) ? DEVELOBEAUTIA_SUITE_DIR : WP_PLUGIN_DIR . \'/develobeautia-suite/\';\r\n    $file = $base . \'includes/class-elementor.php\';\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) && is_readable( $file ) ) {\r\n        require_once $file;\r\n    }\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) || ! method_exists( $manager, \'get_widget_types\' ) ) {\r\n        return;\r\n    }\r\n    $registered = $manager->get_widget_types();\r\n    foreach ( array( \'DeveloBeautia_Elementor_Booking\', \'DeveloBeautia_Elementor_Services\', \'DeveloBeautia_Elementor_Models\', \'DeveloBeautia_Elementor_Before_After\', \'DeveloBeautia_Elementor_Mascot\' ) as $class ) {\r\n        if ( ! class_exists( $class, false ) ) {\r\n            continue;\r\n        }\r\n        $widget = new $class();\r\n        $name = $widget->get_name();\r\n        if ( ! isset( $registered[ $name ] ) ) {\r\n            $manager->register( $widget );\r\n            $registered[ $name ] = $widget;\r\n        }\r\n    }\r\n}, 99 );\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-03 23:55:33\";}i:2;a:14:{s:2:\"id\";i:324;s:5:\"title\";s:66:\"پنل یکپارچه قالب دولوبیوتیا اختصاصی\";s:4:\"code\";s:10287:\"/* پنل یکپارچه قالب دولوبیوتیا */\r\nif (!defined(\'ABSPATH\')) { exit; }\r\nfunction mba_get_options(){\r\n $defaults=array(\'font\'=>\'Tanha\',\'hero_title\'=>\'زیبایی تو، امضای توست\',\'hero_text\'=>\'نتیجه واقعی را ببین، مدل دلخواهت را انتخاب کن و برای یک تجربه دقیق و آرام آماده شو.\',\'hero_cta\'=>\'رزرو آنلاین نوبت\',\'hero_cta_url\'=>\'/DeveloBeautia/booking/\',\'slide1\'=>\'\',\'slide1_mobile\'=>\'\',\'slide2\'=>\'\',\'slide2_mobile\'=>\'\',\'slide3\'=>\'\',\'slide3_mobile\'=>\'\',\'slide4\'=>\'\',\'slide4_mobile\'=>\'\',\'contact_title\'=>\'منتظر دیدنت هستیم\',\'phone\'=>\'02100000000\',\'mobile\'=>\'09000000000\',\'address\'=>\'شهر شما، نشانی سالن شما\',\'instagram\'=>\'https://instagram.com/develobeautia_beauty_center/\',\'whatsapp\'=>\'\',\'custom_css\'=>\'\');\r\n return wp_parse_args((array)get_option(\'mba_options\',array()),$defaults);\r\n}\r\nfunction mba_admin_menu(){\r\n add_menu_page(\'قالب دولوبیوتیا اختصاصی\',\'قالب دولوبیوتیا اختصاصی\',\'manage_options\',\'develobeautia-theme-hub\',\'mba_admin_page\',\'dashicons-art\',2);\r\n add_submenu_page(\'develobeautia-theme-hub\',\'داشبورد\',\'داشبورد\',\'manage_options\',\'develobeautia-theme-hub\',\'mba_admin_page\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'اسلایدر و صفحه اصلی\',\'اسلایدر و صفحه اصلی\',\'manage_options\',\'develobeautia-theme-hub-home\',\'mba_admin_page\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'قبل و بعد\',\'قبل و بعد\',\'edit_posts\',\'edit.php?post_type=develobeautia_before_after\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'ویدیوها و کاورها\',\'ویدیوها و کاورها\',\'edit_posts\',\'edit.php?post_type=develobeautia_video\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'نمونه‌کارها\',\'نمونه‌کارها\',\'edit_posts\',\'edit.php?post_type=develobeautia_portfolio\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'مجله سه‌بعدی\',\'مجله سه‌بعدی\',\'manage_options\',\'develobeautia-atelier\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'خدمات و هدر صفحات\',\'خدمات و هدر صفحات\',\'edit_posts\',\'edit.php?post_type=develobeautia_service\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'مدل‌ها\',\'مدل‌ها\',\'edit_posts\',\'edit.php?post_type=develobeautia_model\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'تماس و فوتر\',\'تماس و فوتر\',\'manage_options\',\'develobeautia-theme-hub-contact\',\'mba_admin_page\');\r\n add_submenu_page(\'develobeautia-theme-hub\',\'ظاهر و فونت\',\'ظاهر و فونت\',\'manage_options\',\'develobeautia-theme-hub-style\',\'mba_admin_page\');\r\n}\r\nadd_action(\'admin_menu\',\'mba_admin_menu\');\r\nfunction mba_save_options(){\r\n if(!current_user_can(\'manage_options\')){wp_die(\'دسترسی ندارید\');}\r\n check_admin_referer(\'mba_save\'); $old=mba_get_options(); $raw=isset($_POST[\'mba\'])?(array)$_POST[\'mba\']:array();\r\n foreach($old as $key=>$value){ if(isset($raw[$key])){$old[$key]=($key===\'custom_css\')?wp_strip_all_tags($raw[$key]):sanitize_text_field($raw[$key]);}}\r\n update_option(\'mba_options\',$old,false); $page=isset($_POST[\'return_page\'])?sanitize_key($_POST[\'return_page\']):\'develobeautia-theme-hub\'; wp_safe_redirect(admin_url(\'admin.php?page=\'.$page.\'&updated=1\')); exit;\r\n}\r\nadd_action(\'admin_post_mba_save\',\'mba_save_options\');\r\nfunction mba_input($key,$label,$o){echo \'<label>\'.esc_html($label).\'<input name=\"mba[\'.esc_attr($key).\']\" value=\"\'.esc_attr($o[$key]).\'\"></label>\';}\r\nfunction mba_admin_page(){\r\n if(!current_user_can(\'manage_options\'))return; $o=mba_get_options(); $page=isset($_GET[\'page\'])?sanitize_key($_GET[\'page\']):\'develobeautia-theme-hub\';\r\n echo \'<div class=\"wrap mba\" dir=\"rtl\"><header class=\"mba-head\"><div><h1>قالب دولوبیوتیا اختصاصی</h1><p>مرکز یکپارچه مدیریت ظاهر و محتوای سایت</p></div><a target=\"_blank\" href=\"\'.esc_url(home_url(\'/\')).\'\">مشاهده سایت ↗</a></header>\';\r\n if(isset($_GET[\'updated\']))echo \'<div class=\"notice notice-success\"><p>تنظیمات با موفقیت ذخیره شد.</p></div>\';\r\n if($page===\'develobeautia-theme-hub\'){\r\n  $cards=array(\r\n   array(\'اسلایدر صفحه اصلی\',\'تصاویر دسکتاپ و موبایل، متن‌ها و CTA\',\'admin.php?page=develobeautia-theme-hub-home\',\'dashicons-images-alt2\'),\r\n   array(\'قبل و بعد\',\'مدیریت جفت تصاویر قبل و بعد\',\'edit.php?post_type=develobeautia_before_after\',\'dashicons-image-flip-horizontal\'),\r\n   array(\'ویدیوها و کاورها\',\'ویدیو، کاور، عنوان و دسته‌بندی\',\'edit.php?post_type=develobeautia_video\',\'dashicons-video-alt3\'),\r\n   array(\'نمونه‌کارها\',\'گالری تصاویر و ویدیوها\',\'edit.php?post_type=develobeautia_portfolio\',\'dashicons-format-gallery\'),\r\n   array(\'مجله سه‌بعدی\',\'صفحات، مدل‌ها و توضیحات\',\'admin.php?page=develobeautia-atelier\',\'dashicons-book-alt\'),\r\n   array(\'خدمات و هدرها\',\'خدمات، تصویر شاخص و متن صفحات\',\'edit.php?post_type=develobeautia_service\',\'dashicons-admin-customizer\'),\r\n   array(\'تماس و فوتر\',\'شماره‌ها، آدرس و شبکه‌های اجتماعی\',\'admin.php?page=develobeautia-theme-hub-contact\',\'dashicons-location-alt\'),\r\n   array(\'ظاهر و فونت\',\'فونت Tanha و CSS تکمیلی\',\'admin.php?page=develobeautia-theme-hub-style\',\'dashicons-art\'));\r\n  echo \'<section class=\"mba-welcome\"><h2>همه‌چیز یک‌جا، مرتب و قابل مدیریت</h2><p>محتوای فعلی حفظ شده و هر بخش از این مرکز قابل ویرایش است.</p></section><div class=\"mba-grid\">\';\r\n  foreach($cards as $c){echo \'<a class=\"mba-card\" href=\"\'.esc_url(admin_url($c[2])).\'\"><span class=\"dashicons \'.esc_attr($c[3]).\'\"></span><div><h3>\'.esc_html($c[0]).\'</h3><p>\'.esc_html($c[1]).\'</p></div><b>‹</b></a>\';}\r\n  echo \'</div>\';\r\n } else {\r\n  echo \'<form method=\"post\" action=\"\'.esc_url(admin_url(\'admin-post.php\')).\'\">\'; wp_nonce_field(\'mba_save\'); echo \'<input type=\"hidden\" name=\"action\" value=\"mba_save\"><input type=\"hidden\" name=\"return_page\" value=\"\'.esc_attr($page).\'\"><section class=\"mba-panel\">\';\r\n  if($page===\'develobeautia-theme-hub-home\'){\r\n   echo \'<h2>اسلایدر و صفحه اصلی</h2><div class=\"mba-fields\">\'; mba_input(\'hero_title\',\'عنوان اصلی\',$o); mba_input(\'hero_text\',\'توضیح کوتاه\',$o); mba_input(\'hero_cta\',\'متن دکمه رزرو\',$o); mba_input(\'hero_cta_url\',\'لینک دکمه رزرو\',$o); echo \'</div><h2>تصاویر اسلایدر</h2><div class=\"mba-fields\">\';\r\n   for($i=1;$i<=4;$i++){mba_input(\'slide\'.$i,\'اسلاید \'.$i.\' دسکتاپ\',$o);mba_input(\'slide\'.$i.\'_mobile\',\'اسلاید \'.$i.\' موبایل\',$o);} echo \'</div>\';\r\n  } elseif($page===\'develobeautia-theme-hub-contact\'){\r\n   echo \'<h2>تماس و فوتر</h2><div class=\"mba-fields\">\'; mba_input(\'contact_title\',\'عنوان بخش تماس\',$o); mba_input(\'phone\',\'تلفن سالن\',$o); mba_input(\'mobile\',\'رزرو و مشاوره\',$o); mba_input(\'address\',\'آدرس\',$o); mba_input(\'instagram\',\'اینستاگرام\',$o); mba_input(\'whatsapp\',\'واتساپ\',$o); echo \'</div>\';\r\n  } else {echo \'<h2>ظاهر و فونت</h2><div class=\"mba-fields\">\';mba_input(\'font\',\'فونت سراسری\',$o);echo \'<label class=\"wide\">CSS تکمیلی<textarea rows=\"8\" name=\"mba[custom_css]\">\'.esc_textarea($o[\'custom_css\']).\'</textarea></label></div>\';}\r\n  echo \'</section>\'; submit_button(\'ذخیره تغییرات\'); echo \'</form>\';\r\n }\r\n echo \'</div>\';\r\n}\r\nfunction mba_admin_css(){if(strpos(isset($_GET[\'page\'])?$_GET[\'page\']:\'\',\'develobeautia-theme-hub\')===false)return;echo \'<style>.mba{max-width:1240px;font-family:Tanha,Tahoma,sans-serif}.mba-head{margin:20px 0;display:flex;align-items:center;justify-content:space-between;padding:28px 32px;border-radius:24px;background:linear-gradient(135deg,#431b35,#a6537f);color:#fff;box-shadow:0 16px 45px #6d315333}.mba-head h1{color:#fff;margin:0 0 8px;font-size:28px}.mba-head p{margin:0;opacity:.85}.mba-head a{color:#fff;border:1px solid #ffffff55;padding:11px 18px;border-radius:12px;text-decoration:none}.mba-welcome,.mba-panel{background:#fff;border:1px solid #eadde5;border-radius:20px;padding:24px;margin:18px 0;box-shadow:0 8px 30px #4d26320a}.mba-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.mba-card{display:flex;gap:16px;align-items:center;background:#fff;border:1px solid #eadde5;padding:22px;border-radius:18px;text-decoration:none;color:#352730;transition:.2s}.mba-card:hover{transform:translateY(-3px);box-shadow:0 12px 30px #6a31521c;border-color:#c98cac}.mba-card .dashicons{font-size:30px;width:38px;height:38px;color:#9a4d75}.mba-card h3{margin:0 0 7px;color:#3d2935}.mba-card p{margin:0;color:#7a6973}.mba-card b{margin-right:auto;font-size:24px}.mba-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.mba label{display:flex;flex-direction:column;gap:7px;font-weight:700}.mba input,.mba textarea{width:100%;border:1px solid #d9c8d2;border-radius:10px;padding:10px 12px;font-family:inherit}.mba .wide{grid-column:1/-1}@media(max-width:900px){.mba-grid,.mba-fields{grid-template-columns:1fr}.mba-head{flex-direction:column;align-items:flex-start;gap:20px}}</style>\';}\r\nadd_action(\'admin_head\',\'mba_admin_css\');\r\nfunction mba_front_css(){ $o=mba_get_options(); echo \'<style id=\"mba-live-style\">html,body,button,input,textarea,select,h1,h2,h3,h4,h5,h6,.page-hero,.hero,.site-header,.site-footer{font-family:\"\'.esc_attr($o[\'font\']).\'\",Tanha,Tahoma,sans-serif!important}.before-after img,.ba-card img{object-fit:contain!important;object-position:center!important}.site-footer{text-align:right!important;direction:rtl}.site-footer p{text-align:justify}\'.wp_strip_all_tags($o[\'custom_css\']).\'</style>\'; }\r\nadd_action(\'wp_head\',\'mba_front_css\',99);\r\nfunction mba_front_data(){ $o=mba_get_options(); $data=wp_json_encode($o); echo \'<script id=\"mba-data\">window.DeveloBeautiaThemeOptions=\'.$data.\';</script>\'; }\r\nadd_action(\'wp_footer\',\'mba_front_data\',99);\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-03 17:08:59\";}i:3;a:14:{s:2:\"id\";i:278;s:5:\"title\";s:41:\"DeveloBeautia Used Media URL Optimization\";s:4:\"code\";s:2324:\"if ( ! defined(\'ABSPATH\') ) return;\r\n\r\nadd_action(\'template_redirect\', function () {\r\n    if ( is_admin() || is_feed() ) return;\r\n\r\n    ob_start(function ($html) {\r\n        $map = [\r\n            \'http://localhost/develobeautia/wp-content/themes/develobeautia-luxe/assets/images/develobeautia-mirror-logo-transparent.png\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\',\r\n\r\n            \'http://localhost/develobeautia/photos/1790196088279.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\',\r\n            \'http://localhost/develobeautia/photos/1790196088290.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\',\r\n            \'http://localhost/develobeautia/photos/1790196094108.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\',\r\n            \'http://localhost/develobeautia/photos/1790196832316.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\',\r\n            \'http://localhost/develobeautia/photos/1790196092137.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\',\r\n            \'http://localhost/develobeautia/photos/1790196088272.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\',\r\n            \'http://localhost/develobeautia/photos/1790196088296.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\',\r\n            \'http://localhost/develobeautia/photos/1790196094176.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\',\r\n            \'http://localhost/develobeautia/photos/1790196088282.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\',\r\n            \'http://localhost/develobeautia/photos/1790196832334.jpg\'\r\n                => \'http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\',\r\n        ];\r\n\r\n        return strtr($html, $map);\r\n    });\r\n}, 0);\r\n\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-02 18:58:34\";}i:4;a:14:{s:2:\"id\";i:266;s:5:\"title\";s:41:\"DeveloBeautia Frontend Asset Optimization\";s:4:\"code\";s:394:\"if ( ! defined(\'ABSPATH\') ) return;\r\n\r\nadd_action(\'wp_enqueue_scripts\', function(){\r\n    if ( ! is_front_page() ) {\r\n        wp_dequeue_style(\'develobeautia-design-studio\');\r\n        wp_dequeue_script(\'develobeautia-design-studio\');\r\n    }\r\n    if ( is_page(\'account\') && ! isset($_GET[\'receipt\']) ) {\r\n        wp_dequeue_script(\'develobeautia-qrcode\');\r\n    }\r\n}, 999);\r\n\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-02 18:02:44\";}i:5;a:14:{s:2:\"id\";i:256;s:5:\"title\";s:37:\"DeveloBeautia Payments & Integrations\";s:4:\"code\";s:11979:\"if ( ! defined(\'ABSPATH\') ) return;\r\n\r\nfunction develobeautia_pay_settings() {\r\n    return wp_parse_args((array)get_option(\'develobeautia_payment_settings\', []), [\r\n        \'enabled\'=>\'0\',\'provider\'=>\'custom\',\'sandbox\'=>\'1\',\'currency\'=>\'IRT\',\r\n        \'default_amount\'=>\'100000\',\'merchant_id\'=>\'\',\'api_key\'=>\'\',\r\n        \'request_endpoint\'=>\'\',\'verify_endpoint\'=>\'\',\'webhook_secret\'=>\'\'\r\n    ]);\r\n}\r\n\r\nadd_action(\'admin_menu\', function(){\r\n    add_submenu_page(\'develobeautia-dashboard\',\'اتصال‌ها و پرداخت\',\'اتصال‌ها و پرداخت\',\'manage_options\',\'develobeautia-payments\',function(){\r\n        if(!current_user_can(\'manage_options\')) return;\r\n        $s=develobeautia_pay_settings();\r\n        if(isset($_POST[\'develobeautia_pay_save\']) && check_admin_referer(\'develobeautia_pay_save_action\')){\r\n            $s=[\r\n                \'enabled\'=>empty($_POST[\'enabled\'])?\'0\':\'1\',\r\n                \'provider\'=>sanitize_key($_POST[\'provider\']??\'custom\'),\r\n                \'sandbox\'=>empty($_POST[\'sandbox\'])?\'0\':\'1\',\r\n                \'currency\'=>in_array($_POST[\'currency\']??\'IRT\',[\'IRT\',\'IRR\'],true)?$_POST[\'currency\']:\'IRT\',\r\n                \'default_amount\'=>(string)absint($_POST[\'default_amount\']??100000),\r\n                \'merchant_id\'=>sanitize_text_field($_POST[\'merchant_id\']??\'\'),\r\n                \'api_key\'=>sanitize_text_field($_POST[\'api_key\']??\'\'),\r\n                \'request_endpoint\'=>esc_url_raw($_POST[\'request_endpoint\']??\'\'),\r\n                \'verify_endpoint\'=>esc_url_raw($_POST[\'verify_endpoint\']??\'\'),\r\n                \'webhook_secret\'=>sanitize_text_field($_POST[\'webhook_secret\']??\'\'),\r\n            ];\r\n            update_option(\'develobeautia_payment_settings\',$s,false);\r\n            echo \'<div class=\"notice notice-success\"><p>تنظیمات ذخیره شد.</p></div>\';\r\n        }\r\n        $callback=admin_url(\'admin-post.php?action=develobeautia_payment_callback\');\r\n        $webhook=rest_url(\'develobeautia/v1/payment/webhook\');\r\n        $sms=function_exists(\'develobeautia_luxe_sms_settings\')?develobeautia_luxe_sms_settings():[];\r\n        echo \'<div class=\"wrap\" dir=\"rtl\"><h1>اتصال‌ها و پرداخت دولوبیوتیا</h1>\';\r\n        echo \'<p>پیامک: <strong>\'.(!empty($sms[\'enabled\'])?\'فعال\':\'آماده اتصال\').\'</strong> — پرداخت: <strong>\'.($s[\'enabled\']===\'1\'?\'فعال\':\'آماده اتصال\').\'</strong></p>\';\r\n        echo \'<form method=\"post\">\'; wp_nonce_field(\'develobeautia_pay_save_action\');\r\n        echo \'<table class=\"form-table\"><tr><th>فعال‌سازی پرداخت</th><td><input type=\"checkbox\" name=\"enabled\" value=\"1\" \'.checked($s[\'enabled\'],\'1\',false).\'></td></tr>\';\r\n        echo \'<tr><th>Provider</th><td><select name=\"provider\">\';\r\n        foreach([\'custom\'=>\'API سفارشی\',\'zarinpal\'=>\'زرین‌پال\',\'idpay\'=>\'IDPay\',\'manual\'=>\'پرداخت دستی\'] as $k=>$v) echo \'<option value=\"\'.esc_attr($k).\'\" \'.selected($s[\'provider\'],$k,false).\'>\'.esc_html($v).\'</option>\';\r\n        echo \'</select></td></tr>\';\r\n        foreach([\'merchant_id\'=>\'Merchant ID\',\'api_key\'=>\'API Key\',\'request_endpoint\'=>\'Request Endpoint\',\'verify_endpoint\'=>\'Verify Endpoint\',\'webhook_secret\'=>\'Webhook Secret\'] as $k=>$label){\r\n            $type=str_contains($k,\'endpoint\')?\'url\':(str_contains($k,\'key\')||str_contains($k,\'secret\')?\'password\':\'text\');\r\n            echo \'<tr><th>\'.esc_html($label).\'</th><td><input class=\"regular-text\" type=\"\'.$type.\'\" name=\"\'.esc_attr($k).\'\" value=\"\'.esc_attr($s[$k]).\'\"></td></tr>\';\r\n        }\r\n        echo \'<tr><th>Sandbox</th><td><input type=\"checkbox\" name=\"sandbox\" value=\"1\" \'.checked($s[\'sandbox\'],\'1\',false).\'></td></tr>\';\r\n        echo \'<tr><th>واحد پول</th><td><select name=\"currency\"><option value=\"IRT\" \'.selected($s[\'currency\'],\'IRT\',false).\'>تومان</option><option value=\"IRR\" \'.selected($s[\'currency\'],\'IRR\',false).\'>ریال</option></select></td></tr>\';\r\n        echo \'<tr><th>مبلغ پیش‌فرض</th><td><input type=\"number\" name=\"default_amount\" value=\"\'.esc_attr($s[\'default_amount\']).\'\"></td></tr>\';\r\n        echo \'<tr><th>Callback</th><td><code>\'.esc_html($callback).\'</code></td></tr><tr><th>Webhook</th><td><code>\'.esc_html($webhook).\'</code></td></tr></table>\';\r\n        submit_button(\'ذخیره تنظیمات\'); echo \'<input type=\"hidden\" name=\"develobeautia_pay_save\" value=\"1\"></form></div>\';\r\n    });\r\n});\r\n\r\nadd_filter(\'do_shortcode_tag\', function($output,$tag){\r\n    if($tag!==\'develobeautia_account\' || !is_user_logged_in()) return $output;\r\n    $s=develobeautia_pay_settings();\r\n    $bookings=get_posts([\'post_type\'=>\'develobeautia_booking\',\'post_status\'=>\'publish\',\'numberposts\'=>20,\'meta_key\'=>\'_develobeautia_booking_user\',\'meta_value\'=>get_current_user_id(),\'orderby\'=>\'date\',\'order\'=>\'DESC\']);\r\n    if(!$bookings) return $output;\r\n    ob_start(); ?>\r\n    <section class=\"account-card develobeautia-payment-center\" id=\"payments\">\r\n      <div class=\"account-card-head\"><div><span class=\"eyebrow\">PAYMENTS</span><h3>پرداخت‌های من</h3></div></div>\r\n      <div class=\"booking-list\">\r\n      <?php foreach($bookings as $b):\r\n        $status=get_post_meta($b->ID,\'_develobeautia_payment_status\',true) ?: \'unpaid\';\r\n        $amount=get_post_meta($b->ID,\'_develobeautia_booking_amount\',true) ?: $s[\'default_amount\'];\r\n        $service=get_post_meta($b->ID,\'_develobeautia_booking_service\',true); ?>\r\n        <article><div><strong><?php echo esc_html($service?:\'رزرو دولوبیوتیا\'); ?></strong><span><?php echo esc_html(number_format_i18n((int)$amount).\' \'.($s[\'currency\']===\'IRT\'?\'تومان\':\'ریال\')); ?></span></div>\r\n        <div class=\"booking-list-actions\"><small><?php echo esc_html([\'unpaid\'=>\'پرداخت نشده\',\'pending\'=>\'در انتظار پرداخت\',\'paid\'=>\'پرداخت شده\',\'failed\'=>\'ناموفق\',\'refunded\'=>\'بازگشت وجه\'][$status]??\'پرداخت نشده\'); ?></small>\r\n        <?php if($status!==\'paid\' && $s[\'enabled\']===\'1\'): ?>\r\n        <a href=\"<?php echo esc_url(wp_nonce_url(admin_url(\'admin-post.php?action=develobeautia_payment_start&booking=\'.$b->ID),\'develobeautia_pay_\'.$b->ID)); ?>\">پرداخت آنلاین</a>\r\n        <?php elseif($status===\'paid\'): ?><span>✓ پرداخت شده</span><?php else: ?><span>درگاه آماده اتصال</span><?php endif; ?>\r\n        </div></article>\r\n      <?php endforeach; ?>\r\n      </div>\r\n    </section><?php\r\n    return $output.ob_get_clean();\r\n},20,2);\r\n\r\nadd_action(\'admin_post_develobeautia_payment_start\', function(){\r\n    if(!is_user_logged_in()) auth_redirect();\r\n    $id=absint($_GET[\'booking\']??0);\r\n    if(!$id || !wp_verify_nonce(sanitize_text_field($_GET[\'_wpnonce\']??\'\'),\'develobeautia_pay_\'.$id)) wp_die(\'درخواست پرداخت معتبر نیست.\');\r\n    $owner=(int)get_post_meta($id,\'_develobeautia_booking_user\',true);\r\n    if($owner!==get_current_user_id() && !current_user_can(\'manage_options\')) wp_die(\'دسترسی غیرمجاز\');\r\n    $s=develobeautia_pay_settings(); $account=home_url(\'/account/\');\r\n    if($s[\'enabled\']!==\'1\'){wp_safe_redirect(add_query_arg(\'payment\',\'not-configured\',$account));exit;}\r\n    if($s[\'provider\']===\'manual\'){update_post_meta($id,\'_develobeautia_payment_status\',\'pending\');wp_safe_redirect(add_query_arg(\'payment\',\'manual\',$account));exit;}\r\n    if(empty($s[\'request_endpoint\']) || (empty($s[\'api_key\'])&&empty($s[\'merchant_id\']))){wp_safe_redirect(add_query_arg(\'payment\',\'not-configured\',$account));exit;}\r\n    $amount=(int)(get_post_meta($id,\'_develobeautia_booking_amount\',true) ?: $s[\'default_amount\']);\r\n    $callback=add_query_arg([\'action\'=>\'develobeautia_payment_callback\',\'booking\'=>$id],admin_url(\'admin-post.php\'));\r\n    $resp=wp_remote_post($s[\'request_endpoint\'],[\'timeout\'=>20,\'headers\'=>[\'Content-Type\'=>\'application/json\',\'Accept\'=>\'application/json\'],\'body\'=>wp_json_encode([\'booking_id\'=>$id,\'amount\'=>$amount,\'currency\'=>$s[\'currency\'],\'callback_url\'=>$callback,\'merchant_id\'=>$s[\'merchant_id\'],\'api_key\'=>$s[\'api_key\'],\'sandbox\'=>$s[\'sandbox\']===\'1\',\'description\'=>\'DeveloBeautia booking #\'.$id])]);\r\n    if(is_wp_error($resp)){update_post_meta($id,\'_develobeautia_payment_status\',\'failed\');wp_safe_redirect(add_query_arg(\'payment\',\'failed\',$account));exit;}\r\n    $data=json_decode(wp_remote_retrieve_body($resp),true); $url=\'\';\r\n    foreach([\'payment_url\',\'redirect_url\',\'url\'] as $k){if(!empty($data[$k])){$url=esc_url_raw($data[$k]);break;}}\r\n    if(!empty($data[\'authority\'])) update_post_meta($id,\'_develobeautia_payment_authority\',sanitize_text_field($data[\'authority\']));\r\n    update_post_meta($id,\'_develobeautia_payment_status\',\'pending\');\r\n    if($url){wp_redirect($url);exit;}\r\n    wp_safe_redirect(add_query_arg(\'payment\',\'pending\',$account));exit;\r\n});\r\n\r\nadd_action(\'admin_post_nopriv_develobeautia_payment_callback\',\'develobeautia_payment_callback_handler\');\r\nadd_action(\'admin_post_develobeautia_payment_callback\',\'develobeautia_payment_callback_handler\');\r\nfunction develobeautia_payment_callback_handler(){\r\n    $id=absint($_REQUEST[\'booking\']??0); if(!$id) wp_die(\'رزرو نامعتبر است.\');\r\n    $s=develobeautia_pay_settings(); $verified=false;\r\n    $ref=sanitize_text_field($_REQUEST[\'ref_id\']??$_REQUEST[\'track_id\']??$_REQUEST[\'reference\']??\'\');\r\n    if(!empty($s[\'verify_endpoint\'])){\r\n        $resp=wp_remote_post($s[\'verify_endpoint\'],[\'timeout\'=>20,\'headers\'=>[\'Content-Type\'=>\'application/json\',\'Accept\'=>\'application/json\'],\'body\'=>wp_json_encode([\'booking_id\'=>$id,\'amount\'=>(int)(get_post_meta($id,\'_develobeautia_booking_amount\',true)?:$s[\'default_amount\']),\'authority\'=>(string)get_post_meta($id,\'_develobeautia_payment_authority\',true),\'merchant_id\'=>$s[\'merchant_id\'],\'api_key\'=>$s[\'api_key\'],\'callback_payload\'=>wp_unslash($_REQUEST)])]);\r\n        if(!is_wp_error($resp)&&wp_remote_retrieve_response_code($resp)<300){$body=json_decode(wp_remote_retrieve_body($resp),true);$verified=!empty($body[\'verified\'])||in_array(strtolower((string)($body[\'status\']??\'\')),[\'paid\',\'success\',\'successful\',\'verified\'],true);if(!$ref)$ref=sanitize_text_field($body[\'ref_id\']??$body[\'reference\']??\'\');}\r\n    } else $verified=in_array(strtolower(sanitize_text_field($_REQUEST[\'status\']??\'\')),[\'paid\',\'success\',\'successful\',\'verified\'],true);\r\n    update_post_meta($id,\'_develobeautia_payment_status\',$verified?\'paid\':\'failed\'); if($ref)update_post_meta($id,\'_develobeautia_payment_ref\',$ref);\r\n    wp_safe_redirect(add_query_arg([\'receipt\'=>$id,\'payment\'=>$verified?\'paid\':\'failed\'],home_url(\'/account/\')).\'#develobeautia-receipt\');exit;\r\n}\r\n\r\nadd_action(\'rest_api_init\',function(){\r\n    register_rest_route(\'develobeautia/v1\',\'/payment/webhook\',[\'methods\'=>\'POST\',\'permission_callback\'=>\'__return_true\',\'callback\'=>function(WP_REST_Request $r){\r\n        $s=develobeautia_pay_settings(); $secret=(string)$s[\'webhook_secret\']; $provided=(string)$r->get_header(\'x-develobeautia-webhook-secret\');\r\n        if(!$secret||!$provided||!hash_equals($secret,$provided)) return new WP_REST_Response([\'ok\'=>false,\'error\'=>\'unauthorized\'],401);\r\n        $id=absint($r->get_param(\'booking_id\')); $status=sanitize_key((string)$r->get_param(\'status\')); $ref=sanitize_text_field((string)$r->get_param(\'ref_id\'));\r\n        if(!$id||get_post_type($id)!==\'develobeautia_booking\') return new WP_REST_Response([\'ok\'=>false,\'error\'=>\'invalid_booking\'],400);\r\n        if(!in_array($status,[\'unpaid\',\'pending\',\'paid\',\'failed\',\'refunded\'],true)) return new WP_REST_Response([\'ok\'=>false,\'error\'=>\'invalid_status\'],400);\r\n        update_post_meta($id,\'_develobeautia_payment_status\',$status); if($ref)update_post_meta($id,\'_develobeautia_payment_ref\',$ref);\r\n        return [\'ok\'=>true,\'booking_id\'=>$id,\'status\'=>$status];\r\n    }]);\r\n});\r\n\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-02 17:18:56\";}i:6;a:14:{s:2:\"id\";i:257;s:5:\"title\";s:44:\"DeveloBeautia Theme Tools & Tanha Customizer\";s:4:\"code\";s:6111:\"if ( ! defined( \'ABSPATH\' ) ) return;\r\n\r\nadd_action(\'customize_register\', function($wp_customize){\r\n    $setting=$wp_customize->get_setting(\'develobeautia_font_family\');\r\n    if($setting) $setting->default=\'Tanha\';\r\n    $control=$wp_customize->get_control(\'develobeautia_font_family\');\r\n    if($control) $control->choices=[\'Tanha\'=>\'تنها — Tanha (پیشنهادی)\',\'Parastoo\'=>\'پرستو\',\'Tahoma\'=>\'Tahoma\',\'sans-serif\'=>\'Sans Serif سیستم\'];\r\n},999);\r\n\r\nadd_action(\'admin_menu\',function(){\r\n    add_submenu_page(\'develobeautia-dashboard\',\'ابزارهای تنظیمات قالب\',\'ابزارهای قالب\',\'manage_options\',\'develobeautia-theme-tools\',function(){\r\n        if(!current_user_can(\'manage_options\'))return;\r\n        $backup=get_option(\'develobeautia_theme_mods_backup\',[]);\r\n        $preview=admin_url(\'customize.php\');\r\n        $export=wp_json_encode(get_theme_mods(),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);\r\n        echo \'<div class=\"wrap\" dir=\"rtl\"><h1>ابزارهای تنظیمات قالب دولوبیوتیا</h1><p>پیش‌نمایش زنده، Backup، Restore، Reset و Export/Import تنظیمات.</p>\';\r\n        echo \'<div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px;margin:20px 0\">\';\r\n        echo \'<section style=\"background:#fff;border:1px solid #ddd;border-radius:14px;padding:18px\"><h2>پیش‌نمایش زنده</h2><a class=\"button button-primary\" href=\"\'.esc_url($preview).\'\">باز کردن Customizer</a></section>\';\r\n        echo \'<section style=\"background:#fff;border:1px solid #ddd;border-radius:14px;padding:18px\"><h2>Backup</h2><a class=\"button\" href=\"\'.esc_url(wp_nonce_url(admin_url(\'admin-post.php?action=develobeautia_theme_tools_backup\'),\'develobeautia_theme_tools_backup\')).\'\">ذخیره پشتیبان تنظیمات</a></section>\';\r\n        echo \'<section style=\"background:#fff;border:1px solid #ddd;border-radius:14px;padding:18px\"><h2>Restore</h2><p>\'.(!empty($backup)?\'پشتیبان موجود است.\':\'هنوز پشتیبان نداریم.\').\'</p>\';\r\n        if(!empty($backup))echo \'<a class=\"button\" href=\"\'.esc_url(wp_nonce_url(admin_url(\'admin-post.php?action=develobeautia_theme_tools_restore\'),\'develobeautia_theme_tools_restore\')).\'\">بازیابی آخرین پشتیبان</a>\';\r\n        echo \'</section>\';\r\n        echo \'<section style=\"background:#fff;border:1px solid #ddd;border-radius:14px;padding:18px\"><h2>Reset</h2><p>رنگ‌ها، تایپوگرافی، گردی کارت و Visibilityها را به پیش‌فرض دولوبیوتیا برمی‌گرداند؛ قبلش Backup می‌گیرد.</p><a class=\"button\" href=\"\'.esc_url(wp_nonce_url(admin_url(\'admin-post.php?action=develobeautia_theme_tools_reset\'),\'develobeautia_theme_tools_reset\')).\'\">بازنشانی کنترل‌شده</a></section></div>\';\r\n        echo \'<h2>Export</h2><textarea readonly style=\"width:100%;min-height:220px;direction:ltr\">\'.esc_textarea($export).\'</textarea>\';\r\n        echo \'<h2>Import</h2><form method=\"post\" action=\"\'.esc_url(admin_url(\'admin-post.php\')).\'\"><input type=\"hidden\" name=\"action\" value=\"develobeautia_theme_tools_import\">\';wp_nonce_field(\'develobeautia_theme_tools_import\');\r\n        echo \'<textarea name=\"mods_json\" style=\"width:100%;min-height:180px;direction:ltr\"></textarea><p><button class=\"button button-primary\">Import تنظیمات</button></p></form></div>\';\r\n    });\r\n});\r\n\r\nfunction develobeautia_theme_tools_backup_now(){update_option(\'develobeautia_theme_mods_backup\',get_theme_mods(),false);}\r\nadd_action(\'admin_post_develobeautia_theme_tools_backup\',function(){if(!current_user_can(\'manage_options\'))wp_die(\'دسترسی غیرمجاز\');check_admin_referer(\'develobeautia_theme_tools_backup\');develobeautia_theme_tools_backup_now();wp_safe_redirect(admin_url(\'admin.php?page=develobeautia-theme-tools\'));exit;});\r\nadd_action(\'admin_post_develobeautia_theme_tools_restore\',function(){if(!current_user_can(\'manage_options\'))wp_die(\'دسترسی غیرمجاز\');check_admin_referer(\'develobeautia_theme_tools_restore\');$b=get_option(\'develobeautia_theme_mods_backup\',[]);if(is_array($b))foreach($b as $k=>$v)set_theme_mod($k,$v);wp_safe_redirect(admin_url(\'admin.php?page=develobeautia-theme-tools\'));exit;});\r\nadd_action(\'admin_post_develobeautia_theme_tools_reset\',function(){if(!current_user_can(\'manage_options\'))wp_die(\'دسترسی غیرمجاز\');check_admin_referer(\'develobeautia_theme_tools_reset\');develobeautia_theme_tools_backup_now();$d=[\'develobeautia_font_family\'=>\'Tanha\',\'develobeautia_body_size\'=>17,\'develobeautia_h1_size\'=>58,\'develobeautia_h2_size\'=>42,\'develobeautia_h3_size\'=>28,\'develobeautia_small_size\'=>12,\'develobeautia_button_size\'=>14,\'develobeautia_body_line_height\'=>1.9,\'develobeautia_card_radius\'=>18,\'develobeautia_wine\'=>\'#b85f7b\',\'develobeautia_wine_dark\'=>\'#7c3f56\',\'develobeautia_paper\'=>\'#fff8fb\',\'develobeautia_rose\'=>\'#efc4d3\',\'develobeautia_gold\'=>\'#d9aa90\',\'develobeautia_ink\'=>\'#49333f\',\'develobeautia_show_trust\'=>true,\'develobeautia_show_about\'=>true,\'develobeautia_show_services\'=>true,\'develobeautia_show_portfolio\'=>true,\'develobeautia_show_before_after\'=>true,\'develobeautia_show_videos\'=>true,\'develobeautia_show_process\'=>true,\'develobeautia_show_journal\'=>true,\'develobeautia_show_reviews\'=>true,\'develobeautia_show_contact\'=>true];foreach($d as $k=>$v)set_theme_mod($k,$v);wp_safe_redirect(admin_url(\'admin.php?page=develobeautia-theme-tools\'));exit;});\r\nadd_action(\'admin_post_develobeautia_theme_tools_import\',function(){if(!current_user_can(\'manage_options\'))wp_die(\'دسترسی غیرمجاز\');check_admin_referer(\'develobeautia_theme_tools_import\');$data=json_decode(wp_unslash($_POST[\'mods_json\']??\'\'),true);if(!is_array($data))wp_die(\'JSON معتبر نیست.\');develobeautia_theme_tools_backup_now();foreach($data as $k=>$v)if(str_starts_with((string)$k,\'develobeautia_\'))set_theme_mod(sanitize_key($k),$v);wp_safe_redirect(admin_url(\'admin.php?page=develobeautia-theme-tools\'));exit;});\r\n\";s:9:\"code_type\";s:3:\"php\";s:8:\"location\";s:10:\"everywhere\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-10-02 17:18:47\";}}}', 'auto');
