flow:hidden!important}.journal-card__media{grid-column:1!important;grid-row:1!important;display:block!important;min-height:210px!important;height:100%!important;overflow:hidden!important}.journal-card__media img{display:block!important;width:100%!important;height:100%!important;object-fit:cover!important;object-position:center!important}.journal-card__body{grid-column:2!important;grid-row:1!important;display:flex!important;flex-direction:column!important;justify-content:center!important;min-width:0!important;padding:12px!important}.journal-meta{display:flex!important;flex-wrap:wrap!important;gap:3px 7px!important;font-size:9px!important;line-height:1.45!important}.journal-card__body h3{font-size:15px!important;line-height:1.55!important;margin:7px 0!important}.journal-card__body p{font-size:11px!important;line-height:1.65!important;display:-webkit-box!important;-webkit-line-clamp:3!important;-webkit-box-orient:vertical!important;overflow:hidden!important;margin:0!important}.journal-read{font-size:11px!important;margin-top:8px!important}\r\n.footer-brand-copy p,.footer-contact p{line-height:1.85!important;text-align:justify!important;text-align-last:right!important;word-break:normal!important}\r\n}\r\n@media(max-width:360px){.journal-card{grid-template-columns:minmax(105px,39%) minmax(0,1fr)!important;min-height:205px!important}.journal-card__media{min-height:205px!important}.journal-card__body{padding:10px!important}.journal-card__body h3{font-size:14px!important}}\r\n/* Follow-up: match theme priority and keep mobile controls clear */\r\n@media(max-width:782px){\r\n.site-header .nav-wrap .brand-cluster{display:flex!important;position:static!important;grid-column:2!important;grid-row:1!important;justify-content:center!important;align-items:center!important;width:100%!important;height:auto!important;transform:none!important}\r\n.site-header .nav-wrap .brand-cluster .mascot-dock{display:none!important}.site-header .nav-wrap .brand-cluster .brand{display:flex!important}\r\n.mds-slider .mds-dots{left:50%!important;right:auto!important;top:12px!important;bottom:auto!important;transform:translateX(-50%)!important;z-index:10!important}\r\n.mds-slider .mds-dot{height:22px!important;min-height:22px!important;width:8px!important;border-radius:999px!important}.mds-slider .mds-dot.is-active{width:22px!important}\r\n}\r\n/* Mobile visibility and pagination cleanup */\r\n@media(max-width:782px){\r\n.site-header .nav-wrap .brand-cluster,.site-header .nav-wrap .brand-cluster .brand,.site-header .nav-wrap .brand-cluster .brand span,.site-header .nav-wrap .brand-cluster .brand span strong,.site-header .nav-wrap .brand-cluster .brand span small{visibility:visible!important}\r\n.site-header .nav-wrap .brand-cluster .brand span small{display:block!important}\r\n.mds-slider .mds-dot,.mds-slider .mds-dot:before,.mds-slider .mds-dot:after{content:none!important;display:block!important;border:0!important;padding:0!important;box-shadow:none!important}\r\n.mds-slider .mds-dot{width:7px!important;height:7px!important;min-height:7px!important;border-radius:999px!important;background:rgba(255,255,255,.72)!important}\r\n.mds-slider .mds-dot.is-active{width:18px!important;height:7px!important;border-radius:999px!important;background:#fff!important}\r\n}\r\n/* Account CTA and mobile menu geometry */\r\n@media(max-width:782px){\r\n.site-header .nav-wrap .mobile-menu-toggle{flex-direction:column!important;justify-content:center!important;align-items:center!important;gap:4px!important}\r\n.site-header .nav-wrap .mobile-menu-toggle span{flex:0 0 18px!important;width:18px!important;min-width:18px!important;height:2px!important}\r\n.account-shell .account-form.account-otp-form button{display:flex!important;align-self:center!important;justify-self:center!important;margin:14px auto 0!important;float:none!important}\r\n}\r\n@media(max-width:782px){\r\n.portfolio-media-card.is-video{height:auto!important;aspect-ratio:9/16!important;align-self:start!important}\r\n.portfolio-media-card.is-video .portfolio-open{height:100%!important;min-height:0!important;aspect-ratio:auto!important}\r\n}\r\n@media(max-width:782px){.journal-card__media{width:100%!important;min-width:0!important;max-width:100%!important}}\r\n@media(max-width:782px){\r\n.site-header .nav-wrap .mobile-menu-toggle{display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:4px!important;padding:0!important;position:static!important;line-height:0!important}\r\n.site-header .nav-wrap .mobile-menu-toggle span{position:static!important;inset:auto!important;display:block!important;flex:none!important;width:18px!important;min-width:18px!important;height:2px!important;margin:0!important;transform:none!important;opacity:1!important;visibility:visible!important;border-radius:2px!important;background:#713c52!important}\r\n}\r\n.portfolio-media-card.is-video{position:relative!important}\r\n.portfolio-sound-toggle{position:absolute!important;top:12px!important;left:12px!important;z-index:12!important;padding:6px 10px!important;border:1px solid rgba(255,255,255,.52)!important;border-radius:999px!important;background:rgba(48,25,37,.72)!important;color:#fff!important;font:600 11px/1.4 inherit!important;cursor:pointer!important;box-shadow:0 4px 14px rgba(29,14,21,.16)!important}\r\n@media(max-width:782px){.portfolio-sound-toggle{top:10px!important;left:10px!important;padding:5px 8px!important;font-size:10px!important}}\r\n/* Compact portfolio sound control */\r\n.portfolio-sound-toggle{height:34px!important;min-height:34px!important;padding:4px 9px!important;box-sizing:border-box!important;font-family:inherit!important;font-size:11px!important;font-weight:600!important;line-height:1!important;white-space:nowrap!important}\r\n@media(max-width:782px){.portfolio-sound-toggle{height:32px!important;min-height:32px!important;padding:4px 8px!important;font-size:10px!important}}\";}', 'off'),
