(2238, 'ihaf_insert_footer', '<script>\r\n(() => {\r\n  const root = \\\'/DeveloBeautia/wp-content/uploads/2026/10/\\\';\r\n  const posters = {\\\'2530\\\':root+\\\'develobeautia-poster-2530.webp\\\',\\\'2529\\\':root+\\\'develobeautia-poster-2529.webp\\\',\\\'2525\\\':root+\\\'develobeautia-poster-2525.webp\\\',\\\'2532\\\':root+\\\'develobeautia-poster-2532.webp\\\'};\r\n  const posterFor = src => Object.keys(posters).find(id => src && src.endsWith(id + \\\'.mp4\\\'));\r\n  const setImage = (image, src, alt) => {\r\n    if (!image || image.dataset.develobeautiaUpdated === \\\'1\\\') return;\r\n    image.src = src; image.removeAttribute(\\\'srcset\\\'); if (alt) image.alt = alt; image.dataset.develobeautiaUpdated = \\\'1\\\';\r\n  };\r\n  const updateMedia = () => {\r\n    const beforeAfter = document.querySelectorAll(\\\'#home-work .before-after-card\\\')[3];\r\n    if (beforeAfter) {\r\n      setImage(beforeAfter.querySelector(\\\'.comparison-before\\\'), root+\\\'DeveloBeautia-Nails-Before.png\\\', \\\'قبل از طراحی ناخن دولوبیوتیا\\\');\r\n      setImage(beforeAfter.querySelector(\\\'.comparison-after img\\\'), root+\\\'DeveloBeautia-Nails-After.webp\\\', \\\'بعد از طراحی ناخن دولوبیوتیا\\\');\r\n    }\r\n    document.querySelectorAll(\\\'.video-frame\\\').forEach(frame => {\r\n      const video = frame.querySelector(\\\'video.local-reel\\\');\r\n      const id = posterFor(video && (video.dataset.src || video.currentSrc || \\\'\\\'));\r\n      if (!id) return;\r\n      setImage(frame.querySelector(\\\'.video-poster-still\\\'), posters[id], (frame.dataset.title || \\\'ویدیوی دولوبیوتیا\\\')+\\\'، کاور ویدیو\\\');\r\n      if (video) video.poster = posters[id];\r\n      frame.style.setProperty(\\\'--video-poster\\\', \\\'url(\\\"\\\'+posters[id]+\\\'\\\")\\\');\r\n    });\r\n    document.querySelectorAll(\\\'.portfolio-media-card.is-video\\\').forEach(card => {\r\n      const id = posterFor(card.dataset.src || \\\'\\\'); if (!id) return;\r\n      card.dataset.poster = posters[id];\r\n      setImage(card.querySelector(\\\'.portfolio-open > img\\\'), posters[id], (card.dataset.title || \\\'ویدیوی دولوبیوتیا\\\')+\\\'، فریم اول ویدیو\\\');\r\n      const video = card.querySelector(\\\'video\\\'); if (video) video.poster = posters[id];\r\n    });\r\n    setImage(document.querySelector(\\\'body.single-develobeautia_service.postid-123 .service-detail-image img\\\'), root+\\\'DeveloBeautia-Hair-Brow-Hero-Feminine.jpg\\\', \\\'خدمات مو و ابرو دولوبیوتیا\\\');\r\n    setImage(document.querySelector(\\\'body.single-develobeautia_service.postid-122 .service-detail-image img\\\'), root+\\\'DeveloBeautia-Nails-Hero-Premium.jpg\\\', \\\'خدمات ناخن دولوبیوتیا\\\');\r\n  };\r\n  if (document.readyState === \\\'loading\\\') document.addEventListener(\\\'DOMContentLoaded\\\', updateMedia, {once:true}); else updateMedia();\r\n})();\r\n\r\n(() => {\r\n  const addPortfolioAudioControls = () => {\r\n    document.querySelectorAll(\\\'.portfolio-media-card.is-video\\\').forEach(card => {\r\n      if (card.dataset.develobeautiaAudioControl === \\\'1\\\') return;\r\n      card.dataset.develobeautiaAudioControl = \\\'1\\\';\r\n      const button = document.createElement(\\\'button\\\');\r\n      button.type = \\\'button\\\';\r\n      button.className = \\\'portfolio-sound-toggle\\\';\r\n      button.textContent = \\\'صدا\\\';\r\n      button.setAttribute(\\\'aria-label\\\', \\\'برای روشن کردن صدای پیش‌نمایش کلیک کنید\\\');\r\n      card.append(button);\r\n      const preview = () => card.querySelector(\\\'.portfolio-first-frame-video\\\') || card.querySelector(\\\'video\\\');\r\n      button.addEventListener(\\\'click\\\', event => {\r\n        event.preventDefault(); event.stopPropagation();\r\n        card.dataset.develobeautiaAudioEnabled = \\\'1\\\';\r\n        button.textContent = \\\'صدا روشن\\\';\r\n        button.setAttribute(\\\'aria-label\\\', \\\'صدای پیش‌نمایش روشن است\\\');\r\n        const video = preview();\r\n        if (video) { video.muted = false; video.volume = 1; video.play().catch(() => {}); }\r\n      });\r\n      card.addEventListener(\\\'pointerenter\\\', () => {\r\n        const video = preview();\r\n        if (video && card.dataset.develobeautiaAudioEnabled === \\\'1\\\') {\r\n          video.muted = false; video.volume = 1; video.play().catch(() => {});\r\n        }\r\n      });\r\n    });\r\n  };\r\n  if (document.readyState === \\\'loading\\\') document.addEventListener(\\\'DOMContentLoaded\\\', addPortfolioAudioControls, { once: true });\r\n  else addPortfolioAudioControls();\r\n})();\r\n</script>', 'auto'),
