(2858, 'develobeautia_sms_settings', 'a:14:{s:7:\"enabled\";b:1;s:13:\"debug_enabled\";b:1;s:8:\"provider\";s:11:\"melipayamak\";s:9:\"send_mode\";s:7:\"pattern\";s:7:\"api_key\";s:0:\"\";s:8:\"username\";s:10:\"9371836073\";s:8:\"password\";s:36:\"d952750f-81a8-4bdb-8019-446f75e93164\";s:6:\"sender\";s:0:\"\";s:8:\"endpoint\";s:0:\"\";s:11:\"admin_phone\";s:11:\"09371836073\";s:9:\"templates\";a:10:{s:9:\"otp_login\";a:5:{s:5:\"label\";s:19:\"کد ورود / OTP\";s:7:\"enabled\";i:1;s:7:\"message\";s:66:\"کاربر گرامی\nکد ورود شما: {code}\nDeveloBeautia\";s:12:\"pattern_code\";s:6:\"553282\";s:14:\"pattern_params\";s:4:\"code\";}s:17:\"booking_new_admin\";a:5:{s:5:\"label\";s:35:\"رزرو جدید برای مدیر\";s:7:\"enabled\";i:1;s:7:\"message\";s:126:\"رزرو جدید {booking_number}: {name}، {service}، {date} {time}، {phone}، مبلغ {amount}، روش {payment_method}\";s:12:\"pattern_code\";s:6:\"553675\";s:14:\"pattern_params\";s:58:\"name,phone,service,date,time,booking_number,booking_status\";}s:24:\"booking_pending_customer\";a:5:{s:5:\"label\";s:41:\"در انتظار پرداخت مشتری\";s:7:\"enabled\";i:1;s:7:\"message\";s:175:\"درخواست نوبت {booking_number} برای {service} در {date} ساعت {time} ثبت شد. برای قطعی شدن رزرو، پرداخت را تکمیل کنید.\";s:12:\"pattern_code\";s:6:\"553676\";s:14:\"pattern_params\";s:44:\"name,service,date,time,booking_number,amount\";}s:25:\"booking_reserved_customer\";a:5:{s:5:\"label\";s:35:\"قطعی شدن رزرو مشتری\";s:7:\"enabled\";i:1;s:7:\"message\";s:115:\"نوبت {booking_number} قطعی شد. {service}، {date} ساعت {time}. روش پرداخت: {payment_method}.\";s:12:\"pattern_code\";s:6:\"553677\";s:14:\"pattern_params\";s:37:\"name,service,date,time,booking_number\";}s:24:\"payment_success_customer\";a:5:{s:5:\"label\";s:32:\"پرداخت موفق مشتری\";s:7:\"enabled\";i:1;s:7:\"message\";s:120:\"پرداخت نوبت {booking_number} با موفقیت انجام شد. مبلغ {amount}. کد پیگیری {ref_id}.\";s:12:\"pattern_code\";s:6:\"553678\";s:14:\"pattern_params\";s:59:\"name,booking_number,amount,payment_met