(3019, 'develobeautia_manager_pages', 'a:6:{s:5:\"about\";a:11:{s:5:\"label\";s:17:\"درباره ما\";s:10:\"hero_title\";s:32:\"روایت ظریف زیبایی\";s:9:\"hero_text\";s:133:\"مشاوره دقیق، اجرای حرفه‌ای و انتخابی هماهنگ با چهره، سبک شخصی و سلامت مو.\";s:10:\"hero_image\";s:82:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\";s:13:\"hero_position\";s:13:\"center center\";s:5:\"title\";s:77:\"زیبایی وقتی ماندگار است که شبیه خودت بماند\";s:4:\"text\";s:318:\"در دولوبیوتیا هر خدمت از گفت‌وگو و مشاوره شروع می‌شود. فرم چهره، تناژ پوست، سلامت مو و نتیجه مورد انتظار کنار هم دیده می‌شوند تا انتخاب نهایی فقط زیبا نباشد؛ مناسب تو هم باشد.\";s:5:\"text2\";s:176:\"نمونه‌های واقعی و مراحل شفاف رزرو کمک می‌کنند پیش از مراجعه تصویر روشن‌تری از نتیجه داشته باشی.\";s:6:\"image1\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\";s:6:\"image2\";s:81:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\";s:6:\"image3\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\";}s:8:\"services\";a:11:{s:5:\"label\";s:17:\"همه خدمات\";s:10:\"hero_title\";s:44:\"خدمات زیبایی دولوبیوتیا\";s:9:\"hero_text\";s:129:\"خدمت دلخواهت را ببین، مدل را انتخاب کن و زمان پیشنهادی را آنلاین ثبت کن.\";s:10:\"hero_image\";s:82:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\";s:13:\"hero_position\";s:11:\"50.0% 93.2%\";s:5:\"title\";s:53:\"یک انتخاب دقیق برای هر استایل\";s:4:\"text\";s:166:\"از تغییر رنگ و احیای مو تا میکاپ، ناخن، ابرو و مژه؛ هر مسیر با گفت‌وگو و مشاوره شروع می‌شود.\";s:5:\"text2\";s:0:\"\";s:6:\"image1\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\";s:6:\"image2\";s:81:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\";s:6:\"image3\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\";}s:9:\"portfolio\";a:11:{s:5:\"label\";s:23:\"نمونه‌کارها\";s:10:\"hero_title\";s:57:\"نمونه‌کارهای واقعی دولوبیوتیا\";s:9:\"hero_text\";s:121:\"تصاویر، قبل و بعد و ویدیوهای واقعی خدمات دولوبیوتیا را یک‌جا ببین.\";s:10:\"hero_image\";s:82:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\";s:13:\"hero_position\";s:10:\"50.0% 3.3%\";s:5:\"title\";s:43:\"آرشیو انتخاب‌های واقعی\";s:4:\"text\";s:109:\"برای انتخاب مدل، نتیجه‌های واقعی را ببین و بعد وارد رزرو شو.\";s:5:\"text2\";s:0:\"\";s:6:\"image1\";s:0:\"\";s:6:\"image2\";s:0:\"\";s:6:\"image3\";s:0:\"\";}s:14:\"beauty-journal\";a:11:{s:5:\"label\";s:23:\"زیبایی‌نامه\";s:10:\"hero_title\";s:94:\"زیبایی‌نامه؛ دانش زیبایی برای انتخاب‌های دقیق‌تر\";s:9:\"hero_text\";s:104:\"راهنماهای تخصصی و کاربردی درباره مو، رنگ، میکاپ و مراقبت.\";s:10:\"hero_image\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\";s:13:\"hero_position\";s:11:\"50.0% 45.6%\";s:5:\"title\";s:30:\"تازه‌ترین مطالب\";s:4:\"text\";s:104:\"پیشنهادهای تازهٔ تیم دولوبیوتیا برای مراقبت آگاهانه‌تر.\";s:5:\"text2\";s:0:\"\";s:6:\"image1\";s:0:\"\";s:6:\"image2\";s:0:\"\";s:6:\"image3\";s:0:\"\";}s:7:\"contact\";a:11:{s:5:\"label\";s:18:\"تماس با ما\";s:10:\"hero_title\";s:50:\"با دولوبیوتیا در ارتباط باش\";s:9:\"hero_text\";s:127:\"برای مشاوره، رزرو و پیگیری نوبت، مستقیم با پذیرش مجموعه در ارتباط باش.\";s:10:\"hero_image\";s:81:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\";s:13:\"hero_position\";s:13:\"center center\";s:5:\"title\";s:32:\"منتظر دیدنت هستیم\";s:4:\"text\";s:113:\"برای مشاوره یا هماهنگی نوبت با پذیرش دولوبیوتیا در ارتباط باش.\";s:5:\"text2\";s:0:\"\";s:6:\"image1\";s:0:\"\";s:6:\"image2\";s:0:\"\";s:6:\"image3\";s:0:\"\";}s:12:\"before-after\";a:11:{s:5:\"label\";s:25:\"صفحه قبل و بعد\";s:10:\"hero_title\";s:16:\"قبل و بعد\";s:9:\"hero_text\";s:107:\"نمونه‌های منتخب از آرشیو واقعی دولوبیوتیا را کنار هم ببین.\";s:10:\"hero_image\";s:80:\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\";s:13:\"hero_position\";s:13:\"center center\";s:5:\"title\";s:42:\"تغییر را در جزئیات ببین\";s:4:\"text\";s:102:\"نوار هر کارت را حرکت بده تا تفاوت قبل و بعد را مقایسه کنی.\";s:5:\"text2\";s:0:\"\";s:6:\"image1\";s:0:\"\";s:6:\"image2\";s:0:\"\";s:6:\"image3\";s:0:\"\";}}', 'off'),
