INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(235, 1, '2026-10-02 15:41:10', '2026-10-02 12:11:10', '', 'صفحه اصلی', '1', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-02 15:41:10', '2026-10-02 12:11:10', '', 100, 'http://localhost/develobeautia/?p=235', 0, 'revision', '', 0),
(236, 1, '2026-10-02 15:41:12', '2026-10-02 12:11:12', '[develobeautia_login][develobeautia_account]', 'حساب کاربری', '1', 'inherit', 'closed', 'closed', '', '101-revision-v1', '', '', '2026-10-02 15:41:12', '2026-10-02 12:11:12', '', 101, 'http://localhost/develobeautia/?p=236', 0, 'revision', '', 0),
(237, 1, '2026-10-02 15:41:14', '2026-10-02 12:11:14', 'در دولوبیوتیا هر انتخاب از مشاوره شروع می‌شود. فرم چهره، تناژ پوست، سبک شخصی و سلامت مو کنار هم دیده می‌شوند تا نتیجه، زیبا و طبیعی باشد.', 'درباره ما', '1', 'inherit', 'closed', 'closed', '', '102-revision-v1', '', '', '2026-10-02 15:41:14', '2026-10-02 12:11:14', '', 102, 'http://localhost/develobeautia/?p=237', 0, 'revision', '', 0),
(238, 1, '2026-10-02 15:41:16', '2026-10-02 12:11:16', 'شهر شما، نشانی سالن شما\nتلفن: ۰۲۱۲۲۰۰۳۹۳۲\nرزرو: ۰۹۱۲۵۷۰۷۴۱۶', 'تماس با ما', '1', 'inherit', 'closed', 'closed', '', '103-revision-v1', '', '', '2026-10-02 15:41:16', '2026-10-02 12:11:16', '', 103, 'http://localhost/develobeautia/?p=238', 0, 'revision', '', 0),
(239, 1, '2026-10-02 15:41:19', '2026-10-02 12:11:19', '', 'خدمات', '1', 'inherit', 'closed', 'closed', '', '104-revision-v1', '', '', '2026-10-02 15:41:19', '2026-10-02 12:11:19', '', 104, 'http://localhost/develobeautia/?p=239', 0, 'revision', '', 0),
(240, 1, '2026-10-02 15:41:21', '2026-10-02 12:11:21', '', 'نمونه کارها', '1', 'inherit', 'closed', 'closed', '', '105-revision-v1', '', '', '2026-10-02 15:41:21', '2026-10-02 12:11:21', '', 105, 'http://localhost/develobeautia/?p=240', 0, 'revision', '', 0),
(241, 1, '2026-10-02 15:41:23', '2026-10-02 12:11:23', '[develobeautia_booking]', 'رزرو نوبت', '1', 'inherit', 'closed', 'closed', '', '107-revision-v1', '', '', '2026-10-02 15:41:23', '2026-10-02 12:11:23', '', 107, 'http://localhost/develobeautia/?p=241', 0, 'revision', '', 0),
(242, 1, '2026-10-02 15:41:25', '2026-10-02 12:11:25', '', 'قبل و بعد', '1', 'inherit', 'closed', 'closed', '', '151-revision-v1', '', '', '2026-10-02 15:41:25', '2026-10-02 12:11:25', '', 151, 'http://localhost/develobeautia/?p=242', 0, 'revision', '', 0),
(243, 1, '2026-10-02 15:41:26', '2026-10-02 12:11:26', '', 'زیبایی‌نامه', '1', 'inherit', 'closed', 'closed', '', '213-revision-v1', '', '', '2026-10-02 15:41:26', '2026-10-02 12:11:26', '', 213, 'http://localhost/develobeautia/?p=243', 0, 'revision', '', 0),
(244, 1, '2026-10-02 15:42:51', '2026-10-02 12:12:51', '', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-02 15:42:51', '2026-10-02 12:12:51', '', 100, 'http://localhost/develobeautia/?p=244', 0, 'revision', '', 0),
(245, 1, '2026-10-02 15:42:54', '2026-10-02 12:12:54', '[develobeautia_login][develobeautia_account]', 'حساب کاربری', 'ورود و عضویت، مدیریت نوبت‌ها، مشاهده رسید و QR رزرو، و تنظیم اطلاعات حساب کاربری دولوبیوتیا.', 'inherit', 'closed', 'closed', '', '101-revision-v1', '', '', '2026-10-02 15:42:54', '2026-10-02 12:12:54', '', 101, 'http://localhost/develobeautia/?p=245', 0, 'revision', '', 0),
(246, 1, '2026-10-02 15:42:56', '2026-10-02 12:12:56', 'در دولوبیوتیا هر انتخاب از مشاوره شروع می‌شود. فرم چهره، تناژ پوست، سبک شخصی و سلامت مو کنار هم دیده می‌شوند تا نتیجه، زیبا و طبیعی باشد.', 'درباره ما', 'درباره دولوبیوتیا؛ رویکرد، خدمات، استانداردهای اجرا و تجربه‌ای دقیق و شخصی‌سازی‌شده در شهر شما تهران.', 'inherit', 'closed', 'closed', '', '102-revision-v1', '', '', '2026-10-02 15:42:56', '2026-10-02 12:12:56', '', 102, 'http://localhost/develobeautia/?p=246', 0, 'revision', '', 0),
(247, 1, '2026-10-02 15:42:58', '2026-10-02 12:12:58', 'شهر شما، نشانی سالن شما\nتلفن: ۰۲۱۲۲۰۰۳۹۳۲\nرزرو: ۰۹۱۲۵۷۰۷۴۱۶', 'تماس با ما', 'راه‌های ارتباط با دولوبیوتیا، آدرس سالن در شهر شما، تلفن، رزرو و دسترسی سریع به پذیرش.', 'inherit', 'closed', 'closed', '', '103-revision-v1', '', '', '2026-10-02 15:42:58', '2026-10-02 12:12:58', '', 103, 'http://localhost/develobeautia/?p=247', 0, 'revision', '', 0),
(248, 1, '2026-10-02 15:43:00', '2026-10-02 12:13:00', '', 'خدمات', 'خدمات زیبایی دولوبیوتیا؛ رنگ و لایت، میکاپ و عروس، ناخن، مو و ابرو با نمونه‌کار واقعی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '104-revision-v1', '', '', '2026-10-02 15:43:00', '2026-10-02 12:13:00', '', 104, 'http://localhost/develobeautia/?p=248', 0, 'revision', '', 0),
(249, 1, '2026-10-02 15:43:02', '2026-10-02 12:13:02', '', 'نمونه کارها', 'نمونه‌کارهای واقعی دولوبیوتیا؛ تصاویر و ویدیوهای منتخب برای انتخاب مدل، سبک و رزرو آگاهانه.', 'inherit', 'closed', 'closed', '', '105-revision-v1', '', '', '2026-10-02 15:43:02', '2026-10-02 12:13:02', '', 105, 'http://localhost/develobeautia/?p=249', 0, 'revision', '', 0),
