(253, 1, '2026-10-02 15:52:30', '2026-10-02 12:22:30', '@font-face{font-family:Tanha;src:url(\"https://cdn.jsdelivr.net/npm/tanha-font@0.10.0/dist/Tanha.woff2\") format(\"woff2\");font-display:swap;font-style:normal;font-weight:400} :root{--font:Tanha,Tahoma,sans-serif!important} html,body,button,input,select,textarea,option,h1,h2,h3,h4,h5,h6,p,a,span,strong,small,label,time{font-family:Tanha,Tahoma,sans-serif!important} html,body{overflow-x:hidden} .service-benefits-pro{width:min(1180px,calc(100% - 32px));margin:22px auto 0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;overflow:hidden;border:1px solid rgba(113,48,67,.12);border-radius:24px;background:linear-gradient(135deg,rgba(255,252,250,.98),rgba(252,241,245,.96));box-shadow:0 18px 48px rgba(84,41,58,.10);direction:rtl} .service-benefits-pro article{min-width:0;display:flex;align-items:center;gap:13px;padding:22px 18px;transition:background .22s ease} .service-benefits-pro article:hover{background:rgba(255,255,255,.58)} .service-benefits-pro article>div{min-width:0} .service-benefits-pro article+article{border-right:1px solid rgba(113,48,67,.10)} .service-benefits-pro article>span{flex:0 0 38px;width:38px;height:38px;display:grid;place-items:center;border:1px solid rgba(183,106,127,.22);border-radius:12px;background:rgba(255,255,255,.72);color:#9b5368;font:800 12px/1 Tanha,Tahoma,sans-serif;box-shadow:inset 0 0 0 1px rgba(255,255,255,.35)} .service-benefits-pro strong{display:block;margin-bottom:3px;color:#5c2f40;font-size:15px;line-height:1.6} .service-benefits-pro small{display:block;color:#71535f;font-size:12px;line-height:1.8} @media(max-width:820px){.service-benefits-pro{grid-template-columns:repeat(2,minmax(0,1fr))}.service-benefits-pro article:nth-child(3),.service-benefits-pro article:nth-child(4){border-top:1px solid rgba(113,48,67,.10)}} @media(max-width:520px){.service-benefits-pro{width:min(100% - 20px,1180px);grid-template-columns:1fr;border-radius:18px}.service-benefits-pro artic