(333, 1, '2026-10-03 23:55:33', '2026-10-03 20:25:33', 'add_action( \'elementor/elements/categories_registered\', static function ( $manager ) {\r\n    if ( ! class_exists( \'\\Elementor\\Widget_Base\' ) ) {\r\n        return;\r\n    }\r\n    $base = defined( \'DEVELOBEAUTIA_SUITE_DIR\' ) ? DEVELOBEAUTIA_SUITE_DIR : WP_PLUGIN_DIR . \'/develobeautia-suite/\';\r\n    $file = $base . \'includes/class-elementor.php\';\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) && is_readable( $file ) ) {\r\n        require_once $file;\r\n    }\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) ) {\r\n        return;\r\n    }\r\n    $categories = method_exists( $manager, \'get_categories\' ) ? $manager->get_categories() : array();\r\n    if ( ! isset( $categories[\'develobeautia\'] ) ) {\r\n        DeveloBeautia_Elementor::category( $manager );\r\n    }\r\n}, 99 );\r\n\r\nadd_action( \'elementor/widgets/register\', static function ( $manager ) {\r\n    if ( ! class_exists( \'\\Elementor\\Widget_Base\' ) ) {\r\n        return;\r\n    }\r\n    $base = defined( \'DEVELOBEAUTIA_SUITE_DIR\' ) ? DEVELOBEAUTIA_SUITE_DIR : WP_PLUGIN_DIR . \'/develobeautia-suite/\';\r\n    $file = $base . \'includes/class-elementor.php\';\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) && is_readable( $file ) ) {\r\n        require_once $file;\r\n    }\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor\', false ) || ! method_exists( $manager, \'get_widget_types\' ) ) {\r\n        return;\r\n    }\r\n    $registered = $manager->get_widget_types();\r\n    foreach ( array( \'DeveloBeautia_Elementor_Booking\', \'DeveloBeautia_Elementor_Services\', \'DeveloBeautia_Elementor_Models\', \'DeveloBeautia_Elementor_Before_After\', \'DeveloBeautia_Elementor_Mascot\' ) as $class ) {\r\n        if ( ! class_exists( $class, false ) ) {\r\n            continue;\r\n        }\r\n        $widget = new $class();\r\n        $name = $widget->get_name();\r\n        if ( ! isset( $registered[ $name ] ) ) {\r\n            $manager->register( $widget );\r\n            $registered[ $name ] = $widget;\r\n        }\r\n    }\r\n}, 99 );', 'DeveloBeautia Elementor Widget Loader', '', 'publish', 'closed', 'closed', '', 'develobeautia-elementor-widget-loader', '', '', '2026-10-03 23:55:33', '2026-10-03 20:25:33', '', 0, 'http://localhost/develobeautia/wpcode/develobeautia-elementor-widget-loader/', 0, 'wpcode', '', 0),
(337, 1, '2026-10-04 00:26:25', '2026-10-03 20:56:25', 'add_action( \'elementor/widgets/register\', static function ( $manager ) {\r\n    if ( ! class_exists( \'\\Elementor\\Widget_Base\' ) || class_exists( \'DeveloBeautia_Elementor_Section_Widget_Base\', false ) ) return;\r\n    abstract class DeveloBeautia_Elementor_Section_Widget_Base extends \\Elementor\\Widget_Base {\r\n        public function get_categories(): array { return array( \'develobeautia\' ); }\r\n        public function get_icon(): string { return \'eicon-apps\'; }\r\n        protected function add_title_control( string $default ): void {\r\n            $this->start_controls_section( \'content\', array( \'label\' => \'محتوا\' ) );\r\n            $this->add_control( \'title\', array( \'label\' => \'عنوان بخش\', \'type\' => \\Elementor\\Controls_Manager::TEXT, \'default\' => $default, \'label_block\' => true ) );\r\n        }\r\n        protected function add_count_control( int $default, int $max ): void {\r\n            $this->add_control( \'count\', array( \'label\' => \'تعداد موارد\', \'type\' => \\Elementor\\Controls_Manager::NUMBER, \'default\' => $default, \'min\' => 1, \'max\' => $max ) );\r\n            $this->end_controls_section();\r\n        }\r\n        protected function render_heading( string $title ): void {\r\n            if ( \'\' !== trim( $title ) ) echo \'<header class=\"section-heading compact\"><h2>\' . esc_html( $title ) . \'</h2></header>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Slider_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_slider\'; }\r\n        public function get_title(): string { return \'اسلایدر صفحه اصلی دولوبیوتیا\'; }\r\n        protected function render(): void {\r\n            echo \'<div class=\"develobeautia-elementor-section develobeautia-elementor-slider\">\';\r\n            if ( function_exists( \'develobeautia_dynamic_slider_render\' ) ) develobeautia_dynamic_slider_render();\r\n            else echo \'<p>اسلایدر دولوبیوتیا در این صفحه در دسترس نیست.</p>\';\r\n            echo \'</div>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Portfolio_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_portfolio\'; }\r\n        public function get_title(): string { return \'نمونه‌کارهای دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'نمونه‌کارهای دولوبیوتیا\' ); $this->add_count_control( 6, 24 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 24, absint( $settings[\'count\'] ?? 6 ) ) );\r\n            $items = function_exists( \'develobeautia_server_works\' ) ? array_slice( (array) develobeautia_server_works(), 0, $limit ) : array();\r\n            echo \'<section class=\"develobeautia-elementor-section develobeautia-elementor-portfolio\">\';\r\n            $this->render_heading( (string) ( $settings[\'title\'] ?? \'\' ) );\r\n            if ( empty( $items ) ) { echo \'<p>هنوز نمونه‌کاری برای نمایش وجود ندارد.</p></section>\'; return; }\r\n            echo \'<div class=\"develobeautia-elementor-media-grid\">\';\r\n            foreach ( $items as $item ) {\r\n                $item = (array) $item; $url = $item[\'url\'] ?? ( $item[\'image\'] ?? \'\' );\r\n                if ( \'\' === $url ) continue;\r\n                $title = $item[\'title\'] ?? \'نمونه‌کار دولوبیوتیا\'; $label = $item[\'label\'] ?? \'\';\r\n                echo \'<article class=\"develobeautia-elementor-media-card\"><a href=\"\' . esc_url( $url ) . \'\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"\' . esc_url( $url ) . \'\" alt=\"\' . esc_attr( $title ) . \'\"><span class=\"develobeautia-elementor-card-copy\">\';\r\n                if ( \'\' !== $label ) echo \'<small>\' . esc_html( $label ) . \'</small>\';\r\n                echo \'<strong>\' . esc_html( $title ) . \'</strong></span></a></article>\';\r\n            }\r\n            echo \'</div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Videos_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_videos\'; }\r\n        public function get_title(): string { return \'ویدیوهای دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'نتیجه‌ها در حرکت\' ); $this->add_count_control( 4, 17 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 17, absint( $settings[\'count\'] ?? 4 ) ) );\r\n            $items = function_exists( \'develobeautia_server_videos\' ) ? array_slice( (array) develobeautia_server_videos(), 0, $limit ) : array();\r\n            echo \'<section class=\"develobeautia-elementor-section develobeautia-elementor-videos work-showcase\"><div class=\"work-showcase__inner\">\';\r\n            $this->render_heading( (string) ( $settings[\'title\'] ?? \'\' ) );\r\n            if ( empty( $items ) ) { echo \'<p>هنوز ویدیویی برای نمایش وجود ندارد.</p></div></section>\'; return; }\r\n            echo \'<div class=\"video-grid work-showcase__videos\">\';\r\n            foreach ( $items as $item ) {\r\n                $item = (array) $item; $video = $item[\'video_file\'] ?? \'\'; $poster = $item[\'poster_url\'] ?? ( $item[\'poster\'] ?? \'\' );\r\n                if ( $video && preg_match( \'/(\\d{4})\\.mp4(?:\\?.*)?$/\', $video, $match ) ) $poster = home_url( \'/wp-content/uploads/2026/10/develobeautia-video-poster-\' . $match[1] . \'.webp\' );\r\n                $title = $item[\'title\'] ?? \'ویدیوی دولوبیوتیا\'; $label = $item[\'label\'] ?? \'\';\r\n                echo \'<article class=\"video-card local-video-card\"><div class=\"video-frame\" data-title=\"\' . esc_attr( $title ) . \'\" style=\"\' . esc_attr( \'--video-poster:url(&quot;\' . esc_url( $poster ) . \'&quot;)\' ) . \'\">\';\r\n                if ( $video ) echo \'<img class=\"video-poster-still\" loading=\"lazy\" src=\"\' . esc_url( $poster ) . \'\" alt=\"\' . esc_attr( $title . \'، کاور ویدیو\' ) . \'\"><video class=\"local-reel\" data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"\' . esc_url( $poster ) . \'\" data-src=\"\' . esc_url( $video ) . \'\"></video><button type=\"button\" class=\"play-mark video-toggle\" aria-label=\"پخش ویدیوی \' . esc_attr( $title ) . \'\">▶</button>\';\r\n                echo \'</div><div><small>\' . esc_html( $label ) . \'</small><h3>\' . esc_html( $title ) . \'</h3><div class=\"video-actions\"><button type=\"button\" class=\"text-button video-toggle\">پخش ویدیو ▶</button></div></div></article>\';\r\n            }\r\n            echo \'</div></div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Magazine_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_magazine\'; }\r\n        public function get_title(): string { return \'مجله تصویری دولوبیوتیا\'; }\r\n        protected function render(): void {\r\n            echo \'<div class=\"develobeautia-elementor-section develobeautia-elementor-magazine\">\';\r\n            if ( locate_template( \'template-parts/magazine.php\' ) ) get_template_part( \'template-parts/magazine\' );\r\n            else echo \'<p>قالب مجله تصویری در دسترس نیست.</p>\';\r\n            echo \'</div>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Articles_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_articles\'; }\r\n        public function get_title(): string { return \'مقاله‌های زیبایی‌نامه\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'تازه‌ترین از زیبایی‌نامه\' ); $this->add_count_control( 4, 12 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 12, absint( $settings[\'count\'] ?? 4 ) ) );\r\n            $posts = get_posts( array( \'post_type\' => \'post\', \'post_status\' => \'publish\', \'numberposts\' => $limit, \'orderby\' => \'date\', \'order\' => \'DESC\' ) );\r\n            echo \'<section class=\"develobeautia-elementor-section home-journal-preview section\"><div class=\"section-heading home-journal-heading\"><div><h2>\' . esc_html( (string) ( $settings[\'title\'] ?? \'\' ) ) . \'</h2></div><a class=\"text-button\" href=\"\' . esc_url( function_exists( \'develobeautia_page_url\' ) ? develobeautia_page_url( \'beauty-journal\', \'/beauty-journal/\' ) : home_url( \'/beauty-journal/\' ) ) . \'\">همه مقاله‌ها ←</a></div>\';\r\n            if ( empty( $posts ) ) { echo \'<p>هنوز مقاله‌ای منتشر نشده است.</p></section>\'; return; }\r\n            echo \'<div class=\"home-journal-grid\">\';\r\n            foreach ( $posts as $post ) {\r\n                $image = get_the_post_thumbnail_url( $post, \'large\' );\r\n                if ( ! $image && function_exists( \'develobeautia_asset\' ) ) $image = develobeautia_asset( \'makeup.jpg\' );\r\n                echo \'<article class=\"home-journal-card reveal\"><a class=\"home-journal-image\" href=\"\' . esc_url( get_permalink( $post ) ) . \'\"><img loading=\"lazy\" src=\"\' . esc_url( $image ) . \'\" alt=\"\' . esc_attr( get_the_title( $post ) ) . \'\"></a><div><small>\' . esc_html( get_the_date( \'j F Y\', $post ) ) . \'</small><h3><a href=\"\' . esc_url( get_permalink( $post ) ) . \'\">\' . esc_html( get_the_title( $post ) ) . \'</a></h3><p>\' . esc_html( wp_trim_words( wp_strip_all_tags( $post->post_content ), 24 ) ) . \'</p><a class=\"teaser-link\" href=\"\' . esc_url( get_permalink( $post ) ) . \'\">مطالعه مقاله ←</a></div></article>\';\r\n            }\r\n            echo \'</div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Contact_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_contact\'; }\r\n        public function get_title(): string { return \'اطلاعات تماس دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'تماس با دولوبیوتیا\' ); $this->end_controls_section(); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $option = static function ( $key, $fallback ) { return function_exists( \'develobeautia_option\' ) ? develobeautia_option( $key, $fallback ) : $fallback; };\r\n            $address = $option( \'address\', \'شهر شما، نشانی سالن شما\' );\r\n            $phone = $option( \'phone\', \'02100000000\' ); $mobile = $option( \'mobile\', \'09000000000\' ); $instagram = $option( \'instagram\', \'\' ); if ( ! $instagram ) $instagram = \'#\';\r\n            $phone_link = preg_replace( \'/[^0-9+]/\', \'\', $phone ); $mobile_link = preg_replace( \'/[^0-9+]/\', \'\', $mobile );\r\n            $instagram_url = $instagram;\r\n            if ( $instagram && ! preg_match( \'~^https?://~i\', $instagram ) ) $instagram_url = \'https://instagram.com/\' . ltrim( $instagram, \'@/ \' );\r\n            echo \'<section class=\"develobeautia-elementor-section develobeautia-elementor-contact section\"><div class=\"section-heading compact\"><h2>\' . esc_html( (string) ( $settings[\'title\'] ?? \'تماس با دولوبیوتیا\' ) ) . \'</h2><p>منتظر دیدنت هستیم</p></div><div class=\"develobeautia-elementor-contact-grid\"><div class=\"develobeautia-elementor-contact-address\"><span>آدرس سالن</span><p>\' . esc_html( $address ) . \'</p><a href=\"\' . esc_url( \'https://maps.google.com/?q=\' . rawurlencode( $address ) ) . \'\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a></div>\';\r\n            if ( $phone_link ) echo \'<a class=\"develobeautia-elementor-contact-item\" href=\"tel:\' . esc_attr( $phone_link ) . \'\"><small>تلفن سالن</small><strong>\' . esc_html( $phone ) . \'</strong></a>\';\r\n            if ( $mobile_link ) echo \'<a class=\"develobeautia-elementor-contact-item\" href=\"tel:\' . esc_attr( $mobile_link ) . \'\"><small>رزرو و مشاوره</small><strong>\' . esc_html( $mobile ) . \'</strong></a>\';\r\n            if ( $instagram_url ) echo \'<a class=\"develobeautia-elementor-contact-item\" href=\"\' . esc_url( $instagram_url ) . \'\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a>\';\r\n            echo \'</div><div class=\"develobeautia-elementor-contact-cta\"><button type=\"button\" class=\"button open-booking\">رزرو نوبت</button></div></section>\';\r\n        }\r\n    }\r\n    foreach ( array( \'DeveloBeautia_Elementor_Slider_Widget\', \'DeveloBeautia_Elementor_Portfolio_Widget\', \'DeveloBeautia_Elementor_Videos_Widget\', \'DeveloBeautia_Elementor_Magazine_Widget\', \'DeveloBeautia_Elementor_Articles_Widget\', \'DeveloBeautia_Elementor_Contact_Widget\' ) as $class ) {\r\n        $widget = new $class(); $registered = method_exists( $manager, \'get_widget_types\' ) ? $manager->get_widget_types() : array();\r\n        if ( ! isset( $registered[ $widget->get_name() ] ) ) $manager->register( $widget );\r\n    }\r\n}, 101 );\r\n\r\nadd_action( \'wp_enqueue_scripts\', static function () {\r\n    if ( is_admin() ) return;\r\n    $preview_id = isset( $_GET[\'elementor-preview\'] ) ? absint( wp_unslash( $_GET[\'elementor-preview\'] ) ) : 0;\r\n    $post_id = $preview_id ?: get_queried_object_id();\r\n    $elementor_data = $post_id ? get_post_meta( $post_id, \'_elementor_data\', true ) : \'\';\r\n    if ( ! is_string( $elementor_data ) ) $elementor_data = \'\';\r\n    $types = array( \'develobeautia_slider\', \'develobeautia_portfolio\', \'develobeautia_videos\', \'develobeautia_magazine\', \'develobeautia_articles\', \'develobeautia_contact\' );\r\n    $has_widget = $preview_id > 0;\r\n    foreach ( $types as $type ) if ( false !== strpos( $elementor_data, $type ) ) { $has_widget = true; break; }\r\n    if ( ! $has_widget ) return;\r\n    wp_register_style( \'develobeautia-elementor-section-widgets\', false, array(), \'1.0.0\' );\r\n    wp_enqueue_style( \'develobeautia-elementor-section-widgets\' );\r\n    wp_add_inline_style( \'develobeautia-elementor-section-widgets\', \'.develobeautia-elementor-section{direction:rtl;min-width:0;max-width:100%}.develobeautia-elementor-media-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.develobeautia-elementor-media-card{min-width:0;overflow:hidden;border:1px solid rgba(70,80,72,.12);border-radius:18px;background:#fff;box-shadow:0 12px 34px rgba(36,47,40,.08)}.develobeautia-elementor-media-card>a{display:block;height:100%;color:inherit;text-decoration:none}.develobeautia-elementor-media-card img{display:block;width:100%;aspect-ratio:4/5;object-fit:cover}.develobeautia-elementor-card-copy{display:grid;gap:7px;padding:14px 16px 18px}.develobeautia-elementor-card-copy small,.develobeautia-elementor-contact-item small{color:#778078;font-size:.76rem}.develobeautia-elementor-card-copy strong{font-size:1rem;line-height:1.6}.develobeautia-elementor-videos .video-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.develobeautia-elementor-videos .video-card{min-width:0}.develobeautia-elementor-videos video{width:100%;max-width:100%}.develobeautia-elementor-magazine{overflow:hidden}.develobeautia-elementor-contact-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:14px}.develobeautia-elementor-contact-address,.develobeautia-elementor-contact-item{display:grid;align-content:center;gap:8px;min-width:0;padding:20px;border:1px solid rgba(70,80,72,.12);border-radius:16px;background:#fff;color:inherit;text-decoration:none}.develobeautia-elementor-contact-address span{font-size:.8rem;color:#778078}.develobeautia-elementor-contact-address p{margin:0;line-height:1.8}.develobeautia-elementor-contact-address>a{color:inherit;text-decoration:underline;text-underline-offset:4px}.develobeautia-elementor-contact-item strong{overflow-wrap:anywhere}.develobeautia-elementor-contact-cta{margin-top:20px}@media(max-width:900px){.develobeautia-elementor-media-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.develobeautia-elementor-videos .video-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.develobeautia-elementor-contact-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.develobeautia-elementor-media-grid{gap:10px}.develobeautia-elementor-card-copy{padding:10px 11px 13px}.develobeautia-elementor-contact-grid{grid-template-columns:1fr}.develobeautia-elementor-contact-address,.develobeautia-elementor-contact-item{padding:15px}.develobeautia-elementor-videos .video-grid{gap:12px}}\' );\r\n    if ( ( $preview_id || false !== strpos( $elementor_data, \'develobeautia_magazine\' ) ) && function_exists( \'develobeautia_atelier_data\' ) && ! wp_script_is( \'develobeautia-atelier\', \'enqueued\' ) ) {\r\n        wp_enqueue_style( \'develobeautia-elementor-atelier\', get_theme_file_uri( \'assets/css/atelier.css\' ), array(), null );\r\n        wp_enqueue_script( \'develobeautia-elementor-atelier\', get_theme_file_uri( \'assets/js/atelier.js\' ), array(), null, true );\r\n        wp_localize_script( \'develobeautia-elementor-atelier\', \'DeveloBeautiaAtelier\', develobeautia_atelier_data() );\r\n    }\r\n}, 30 );\r\n\r\nadd_filter( \'template_include\', static function ( $template ) {\r\n    $preview_id = isset( $_GET[\'elementor-preview\'] ) ? absint( wp_unslash( $_GET[\'elementor-preview\'] ) ) : 0;\r\n    $is_develobeautia_home = is_front_page() && 100 === (int) get_queried_object_id();\r\n    if ( 100 === $preview_id || $is_develobeautia_home ) return get_theme_file_path( \'page.php\' );\r\n    return $template;\r\n}, 9999 );\r\n\r\nadd_action( \'wp_head\', static function () {\r\n    if ( is_page( 100 ) ) echo \'<style>body.page-id-100 #main{padding-top:40px!important}body.page-id-100 #main>article>h1{display:none!important}body.page-id-100 .mds-picture img{object-fit:cover!important}body.page-id-100 .mds-transition-fade .mds-slide{transition:opacity .9s ease,visibility 0s linear .9s!important}body.page-id-100 .mds-transition-fade .mds-slide.is-active{transition-delay:0s!important}</style>\';\r\n}, 99 );\r\n\r\nadd_action( \'elementor/widgets/register\', static function ( $manager ) {\r\n    if ( ! class_exists( \'DeveloBeautia_Elementor_Section_Widget_Base\', false ) || class_exists( \'DeveloBeautia_Elementor_Trust_Widget\', false ) ) return;\r\n    final class DeveloBeautia_Elementor_Trust_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_trust\'; }\r\n        public function get_title(): string { return \'مزیت‌های تجربه دولوبیوتیا\'; }\r\n        protected function render(): void {\r\n            echo \'<section class=\"trust-strip trust-strip-pro develobeautia-elementor-section develobeautia-elementor-trust\" aria-label=\"مزیت‌های تجربه دولوبیوتیا\"><div><span>۰۱</span><strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small></div><div><span>۰۲</span><strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small></div><div><span>۰۳</span><strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small></div><div><span>۰۴</span><strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></div></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Before_After_Archive_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_before_after_archive\'; }\r\n        public function get_title(): string { return \'آرشیو قبل و بعد دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'قبل و بعد\' ); $this->add_count_control( 4, 4 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 4, absint( $settings[\'count\'] ?? 4 ) ) );\r\n            echo \'<section class=\"develobeautia-elementor-section work-showcase__group work-showcase__group--before-after\"><div class=\"work-showcase__label\"><span>01</span><div><h3>\' . esc_html( (string) ( $settings[\'title\'] ?? \'قبل و بعد\' ) ) . \'</h3><p>جزئیات هر تغییر را کنار هم ببین.</p></div></div>\';\r\n            if ( function_exists( \'develobeautia_before_after_grid\' ) ) echo develobeautia_before_after_grid( $limit );\r\n            echo \'</section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Booking_Steps_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_booking_steps\'; }\r\n        public function get_title(): string { return \'مراحل رزرو دولوبیوتیا\'; }\r\n        protected function register_controls(): void {\r\n            $this->add_title_control( \'BOOK NOW\' );\r\n            $this->add_control( \'button\', array( \'label\' => \'متن دکمه\', \'type\' => \\Elementor\\Controls_Manager::TEXT, \'default\' => \'همین حالا رزرو کن\', \'label_block\' => true ) );\r\n            $this->end_controls_section();\r\n        }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            echo \'<section class=\"process section develobeautia-elementor-section develobeautia-elementor-booking-steps\" id=\"booking\"><div class=\"section-heading section-heading--single\"><h2 class=\"section-title-only\">\' . esc_html( (string) ( $settings[\'title\'] ?? \'BOOK NOW\' ) ) . \'</h2></div><div class=\"steps\"><div><span>۱</span><strong>انتخاب خدمت</strong><small>خدمت و متخصص</small></div><div><span>۲</span><strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small></div><div><span>۳</span><strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small></div><div><span>۴</span><strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small></div></div><button type=\"button\" class=\"button open-booking\">\' . esc_html( (string) ( $settings[\'button\'] ?? \'همین حالا رزرو کن\' ) ) . \'</button></section>\';\r\n        }\r\n    }\r\n    final class DeveloBeautia_Elementor_Reviews_Widget extends DeveloBeautia_Elementor_Section_Widget_Base {\r\n        public function get_name(): string { return \'develobeautia_reviews\'; }\r\n        public function get_title(): string { return \'بازخوردهای دولوبیوتیا\'; }\r\n        protected function register_controls(): void { $this->add_title_control( \'حس خوبِ اعتماد\' ); $this->add_count_control( 6, 12 ); }\r\n        protected function render(): void {\r\n            $settings = $this->get_settings_for_display();\r\n            $limit = max( 1, min( 12, absint( $settings[\'count\'] ?? 6 ) ) );\r\n            $posts = get_posts( array( \'post_type\' => \'develobeautia_review\', \'post_status\' => \'publish\', \'numberposts\' => $limit, \'orderby\' => \'menu_order\', \'order\' => \'ASC\' ) );\r\n            if ( empty( $posts ) ) return;\r\n            echo \'<section class=\"reviews section develobeautia-elementor-section develobeautia-elementor-reviews\"><div class=\"section-heading compact\"><span class=\"eyebrow\">از زبان همراهان دولوبیوتیا</span><h2>\' . esc_html( (string) ( $settings[\'title\'] ?? \'حس خوبِ اعتماد\' ) ) . \'</h2><p>بازخوردهای عمومی و مثبت منتشرشده در صفحه رسمی دولوبیوتیا.</p></div><div class=\"review-grid\">\';\r\n            foreach ( $posts as $review ) {\r\n                $name = get_post_meta( $review->ID, \'_develobeautia_reviewer\', true ) ?: \'همراه دولوبیوتیا\';\r\n                $source = get_post_meta( $review->ID, \'_develobeautia_review_source\', true ) ?: \'اینستاگرام دولوبیوتیا\';\r\n                echo \'<blockquote><span>“</span><p>\' . esc_html( wp_strip_all_tags( $review->post_content ) ) . \'</p><footer><strong>\' . esc_html( $name ) . \'</strong><small>\' . esc_html( $source ) . \'</small></footer></blockquote>\';\r\n            }\r\n            echo \'</div></section>\';\r\n        }\r\n    }\r\n    foreach ( array( \'DeveloBeautia_Elementor_Trust_Widget\', \'DeveloBeautia_Elementor_Before_After_Archive_Widget\', \'DeveloBeautia_Elementor_Booking_Steps_Widget\', \'DeveloBeautia_Elementor_Reviews_Widget\' ) as $class ) {\r\n        $widget = new $class(); $registered = method_exists( $manager, \'get_widget_types\' ) ? $manager->get_widget_types() : array();\r\n        if ( ! isset( $registered[ $widget->get_name() ] ) ) $manager->register( $widget );\r\n    }\r\n}, 102 );', 'DeveloBeautia Elementor Section Widgets', '', 'publish', 'closed', 'closed', '', 'develobeautia-elementor-section-widgets', '', '', '2026-10-04 01:04:42', '2026-10-03 21:34:42', '', 0, 'http://localhost/develobeautia/?post_type=wpcode&#038;p=337', 0, 'wpcode', '', 0),
(342, 1, '2026-10-04 00:53:06', '2026-10-03 21:23:06', '', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 00:53:06', '2026-10-03 21:23:06', '', 100, 'http://localhost/develobeautia/?p=342', 0, 'revision', '', 0),
(343, 1, '2026-10-04 00:53:06', '2026-10-03 21:23:06', '', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 00:53:06', '2026-10-03 21:23:06', '', 100, 'http://localhost/develobeautia/?p=343', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(344, 1, '2026-10-04 00:53:06', '2026-10-03 21:23:06', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section><header><h2>نمونه‌کارهای دولوبیوتیا</h2></header><article><a href=\"http://localhost/develobeautia/photos/1790196088272.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای تمیز\"><small>رنگ و مو</small><strong>باب نقره‌ای تمیز</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088279.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"موج‌های بلوند روشن\"><small>رنگ و مو</small><strong>موج‌های بلوند روشن</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088282.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088282.jpg\" alt=\"بلوند دودی بلند\"><small>بالیاژ</small><strong>بلوند دودی بلند</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088290.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب زاویه‌دار\"><small>استایل مو</small><strong>باب زاویه‌دار</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196092100.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092100.jpg\" alt=\"باب بلوند کوتاه\"><small>کات و رنگ</small><strong>باب بلوند کوتاه</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196092137.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"موج صدفی\"><small>فرم و حالت</small><strong>موج صدفی</strong></a></article></section>				\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 00:53:06', '2026-10-03 21:23:06', '', 100, 'http://localhost/develobeautia/?p=344', 0, 'revision', '', 0),
(345, 1, '2026-10-04 02:50:45', '2026-10-03 23:20:45', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section><header><h2>نمونه‌کارهای دولوبیوتیا</h2></header><article><a href=\"http://localhost/develobeautia/photos/1790196088272.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای تمیز\"><small>رنگ و مو</small><strong>باب نقره‌ای تمیز</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088279.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"موج‌های بلوند روشن\"><small>رنگ و مو</small><strong>موج‌های بلوند روشن</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088282.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088282.jpg\" alt=\"بلوند دودی بلند\"><small>بالیاژ</small><strong>بلوند دودی بلند</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088290.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب زاویه‌دار\"><small>استایل مو</small><strong>باب زاویه‌دار</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196092100.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092100.jpg\" alt=\"باب بلوند کوتاه\"><small>کات و رنگ</small><strong>باب بلوند کوتاه</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196092137.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"موج صدفی\"><small>فرم و حالت</small><strong>موج صدفی</strong></a></article></section>				\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:50:45', '2026-10-03 23:20:45', '', 100, 'http://localhost/develobeautia/?p=345', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(346, 1, '2026-10-04 02:50:45', '2026-10-03 23:20:45', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section><header><h2>نمونه‌کارهای دولوبیوتیا</h2></header><article><a href=\"http://localhost/develobeautia/photos/1790196088272.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای تمیز\"><small>رنگ و مو</small><strong>باب نقره‌ای تمیز</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088279.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"موج‌های بلوند روشن\"><small>رنگ و مو</small><strong>موج‌های بلوند روشن</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088282.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088282.jpg\" alt=\"بلوند دودی بلند\"><small>بالیاژ</small><strong>بلوند دودی بلند</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196088290.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب زاویه‌دار\"><small>استایل مو</small><strong>باب زاویه‌دار</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196092100.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092100.jpg\" alt=\"باب بلوند کوتاه\"><small>کات و رنگ</small><strong>باب بلوند کوتاه</strong></a></article><article><a href=\"http://localhost/develobeautia/photos/1790196092137.jpg\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"موج صدفی\"><small>فرم و حالت</small><strong>موج صدفی</strong></a></article></section>				\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:50:45', '2026-10-03 23:20:45', '', 100, 'http://localhost/develobeautia/?p=346', 0, 'revision', '', 0),
(347, 1, '2026-10-04 02:50:46', '2026-10-03 23:20:46', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:50:46', '2026-10-03 23:20:46', '', 100, 'http://localhost/develobeautia/?p=347', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(348, 1, '2026-10-04 02:53:10', '2026-10-03 23:23:10', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:53:10', '2026-10-03 23:23:10', '', 100, 'http://localhost/develobeautia/?p=348', 0, 'revision', '', 0),
(349, 1, '2026-10-04 02:53:10', '2026-10-03 23:23:10', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:53:10', '2026-10-03 23:23:10', '', 100, 'http://localhost/develobeautia/?p=349', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(350, 1, '2026-10-04 02:53:10', '2026-10-03 23:23:10', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:53:10', '2026-10-03 23:23:10', '', 100, 'http://localhost/develobeautia/?p=350', 0, 'revision', '', 0),
(351, 1, '2026-10-04 02:53:19', '2026-10-03 23:23:19', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:53:19', '2026-10-03 23:23:19', '', 100, 'http://localhost/develobeautia/?p=351', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(352, 1, '2026-10-04 02:53:19', '2026-10-03 23:23:19', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n					<section><h2>خدمات تخصصی دولوبیوتیا</h2><article>01<h3>مو و ابرو</h3><p>هیرکات، براشینگ، لیفت و اصلاح ابرو و میکروبلیدینگ.</p><button data-service=\"مو و ابرو\">رزرو این خدمت ←</button></article><article>02<h3>خدمات ناخن</h3><p>کاشت، ژل، لمینت، ترمیم و طراحی ظریف ناخن.</p><button data-service=\"خدمات ناخن\">رزرو این خدمت ←</button></article><article>03<h3>میکاپ و عروس</h3><p>طراحی چهره، میکاپ لایت و مراسم و مشاوره تخصصی عروس.</p><button data-service=\"میکاپ و عروس\">رزرو این خدمت ←</button></article><article>04<h3>رنگ و لایت</h3><p>بالیاژ، آمبره، هایلایت، اصلاح رنگ و انتخاب تناژ متناسب با پوست و سلامت مو.</p><button data-service=\"رنگ و لایت\">رزرو این خدمت ←</button></article></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:53:19', '2026-10-03 23:23:19', '', 100, 'http://localhost/develobeautia/?p=352', 0, 'revision', '', 0),
(353, 1, '2026-10-04 02:53:19', '2026-10-03 23:23:19', '<section style=\"--mds-desktop:760px;--mds-mobile:680px;--mds-overlay:0.42\" data-autoplay=\"1\" data-delay=\"5500\" aria-label=\"اسلایدر دولوبیوتیا\">\n                    <article aria-hidden=\"false\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"زیبایی تو، امضای توست\" fetchpriority=\"high\"></picture>\n                    DEVELOBEAUTIA                    <h1>زیبایی تو، امضای توست</h1>\n                    <p>میکاپ حرفه‌ای، ظریف و هماهنگ با چهره و استایل تو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/\">رزرو میکاپ</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">دیدن نمونه‌کارها</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"درخشش رنگ، با امضای دولوبیوتیا\" loading=\"lazy\"></picture>\n                    COLOR &amp; SHINE                    <h1>درخشش رنگ، با امضای دولوبیوتیا</h1>\n                    <p>رنگ و لایت حرفه‌ای با انتخاب تناژ دقیق و مراقبت از سلامت مو.</p>\n                        <a href=\"http://localhost/develobeautia/services/\">خدمات رنگ و مو</a>                        <a href=\"http://localhost/develobeautia/portfolio/\">نمونه‌کارهای واقعی</a>                    \n            </article>\n                    <article aria-hidden=\"true\">\n                <picture><source media=\"(max-width: 782px)\" srcset=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\"><img src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"جزئیات ظریف، نتیجه ماندگار\" loading=\"lazy\"></picture>\n                    NAIL ATELIER                    <h1>جزئیات ظریف، نتیجه ماندگار</h1>\n                    <p>طراحی و خدمات ناخن با اجرای تمیز، شیک و شخصی‌سازی‌شده.</p>\n                        <a href=\"http://localhost/develobeautia/develobeautia-service/nails/\">رزرو خدمات ناخن</a>                        <a href=\"http://localhost/develobeautia/services/\">مشاهده خدمات</a>                    \n            </article>\n        <button type=\"button\" aria-label=\"اسلاید قبلی\">‹</button><button type=\"button\" aria-label=\"اسلاید بعدی\">›</button>\n        <button type=\"button\" aria-label=\"رفتن به اسلاید 1\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 2\"></button><button type=\"button\" aria-label=\"رفتن به اسلاید 3\"></button>\n    </section>\n					<section aria-label=\"مزیت‌های تجربه دولوبیوتیا\">۰۱<strong>مشاوره اختصاصی</strong><small>انتخاب فرم، رنگ و تکنیک متناسب با چهره و سبک تو</small>۰۲<strong>رزرو شفاف و مرحله‌ای</strong><small>خدمت، مدل، تاریخ و زمان؛ بدون مسیر پیچیده</small>۰۳<strong>آرشیو واقعی نتایج</strong><small>تصاویر و ویدیوهای منتخب از اجرای واقعی خدمات دولوبیوتیا</small>۰۴<strong>دسترسی سریع و مشخص</strong><small>تهران، شهر شما، مجتمع تجاری داریوش</small></section>				\n<section id=\"portfolio\" data-real-magazine-ready=\"true\" aria-label=\"مجلهٔ مدل‌های دولوبیوتیا\">\n    <header>\n        <h2>DEVELOBEAUTIA · LOOKBOOK</h2>\n    </header>\n                    <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                    <p>مدل موردنظرت را انتخاب کن و از همان صفحه برای رزرو نوبت اقدام کن.</p>\n                    <small>DEVELOBEAUTIA · YOUR CITY</small>\n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی DeveloBeautia\">                        DeveloBeautia\n                        <small>Luxury Edition</small>\n                        <strong>DEVELOBEAUTIA JOURNAL</strong>\n                        Luxury Lookbook · Hair, Makeup &amp; Beauty Selection\n                    برای باز کردن لمس کن\n            <canvas aria-hidden=\"true\"></canvas>\n                <article>\n                    <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"جلد مجله دولوبیوتیا\">                    \n                        <img src=\"http://localhost/develobeautia/wp-content/themes/develobeautia-luxe-wpvibe-backup/assets/images/develobeautia-mirror-logo-transparent.png\" alt=\"لوگوی دولوبیوتیا\">                        <small>DEVELOBEAUTIA · LOOKBOOK</small>\n                        <h3>DEVELOBEAUTIA JOURNAL</h3>\n                        <p>Luxury Lookbook · Hair, Makeup &amp; Beauty Selection</p>\n                        برای دیدن صفحات، به چپ بکش ←\n                </article>\n                <article>\n                    درباره دولوبیوتیا\n                    <h3>دولوبیوتیا</h3>\n                    <p>دولوبیوتیا فضایی برای انتخاب آگاهانه و زیبایی شخصی‌سازی‌شده است. هر تجربه با گفت‌وگو و شناخت فرم چهره، تناژ پوست، سلامت مو و سبک زندگی تو آغاز می‌شود؛ سپس متخصصان دولوبیوتیا با دقت و ظرافت، مدلی را اجرا می‌کنند که فقط زیبا نیست، بلکه با خودِ تو هماهنگ است. این مجله دریچه‌ای به نگاه، جزئیات و نتیجه‌های واقعی دولوبیوتیا است تا پیش از رزرو، انتخابی روشن‌تر و مطمئن‌تر داشته باشی.</p>\n                    <a href=\"http://localhost/develobeautia/booking/\">رزرو و مشاوره</a>\n                </article>\n                                    <article>\n                        <h3>بلوند صدفی موج‌دار</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088279.jpg\" alt=\"بلوند صدفی موج‌دار\">                        <p>موج‌های روشن و تناژ صدفی؛ انتخاب نهایی رنگ پس از مشاوره و بررسی مو انجام می‌شود.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-1\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب بلوند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088290.jpg\" alt=\"باب بلوند\">                        <p>فرم کوتاه و منظم با قاب روشن دور صورت.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-2\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>موج کاراملی</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196094108.jpg\" alt=\"موج کاراملی\">                        <p>تناژ گرم کاراملی با موج‌های نرم و درخشان.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-3\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>میکاپ لایت</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196832316.jpg\" alt=\"میکاپ لایت\">                        <p>آرایش ظریف چشم و فینیش طبیعی پوست.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-4\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>بلوند بلند</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196092137.jpg\" alt=\"بلوند بلند\">                        <p>ترکیب لایت روشن با فرم و حالت مو.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-5\">رزرو این مدل</a>                    </article>\n                                    <article>\n                        <h3>باب نقره‌ای</h3>\n                        <img loading=\"lazy\" src=\"http://localhost/develobeautia/photos/1790196088272.jpg\" alt=\"باب نقره‌ای\">                        <p>کوتاهی منظم با تناژ سرد و روشن.</p>\n                        <a href=\"http://localhost/develobeautia/booking/?catalogue_model=develobeautia-6\">رزرو این مدل</a>                    </article>\n            ورق بزن\n            <svg viewBox=\"0 0 24 24\"><path d=\"M8.8 13V4.8a1.9 1.9 0 0 1 3.8 0V10h.5V7.7a1.7 1.7 0 0 1 3.4 0V10h.5V9a1.6 1.6 0 0 1 3.2 0v4.5c0 4.2-3 7.2-7.2 7.2h-1.2c-2.1 0-3.6-.8-4.8-2.2l-3-3.5a1.7 1.7 0 0 1 2.5-2.3l2.3 2.4V13Z\"/></svg>\n    <p>برای ورق‌زدن صفحه را بکش؛ برای خواندن جزئیات از بزرگ‌نمایی استفاده کن.</p>\n        <button type=\"button\" aria-label=\"صفحه قبلی\">›</button>\n            <strong>مجله دولوبیوتیا</strong>\n            جلد جلو\n        <button type=\"button\" aria-pressed=\"false\">بزرگ‌نمایی صفحه</button>\n        <button type=\"button\" aria-label=\"صفحه بعدی\">‹</button>\n    جلد جلو\n    <p aria-live=\"polite\"></p>\n</section>\n					<section>01<h3>قبل و بعد</h3><p>جزئیات هر تغییر را کنار هم ببین.</p><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از باب نقره‌ای و فرم نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از باب نقره‌ای و فرم نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد باب نقره‌ای و فرم نهایی\">↔نمونه تغییر 01<h3>باب نقره‌ای و فرم نهایی</h3><p>دو قاب منتخب از تناژ سرد و فرم دقیق کوتاهی.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از موج کاراملی و درخشش مو\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از موج کاراملی و درخشش مو\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد موج کاراملی و درخشش مو\">↔نمونه تغییر 02<h3>موج کاراملی و درخشش مو</h3><p>حرکت رنگ و حالت مو در دو قاب از آرشیو دولوبیوتیا.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"قبل از بلوند روشن و قاب صورت\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"بعد از بلوند روشن و قاب صورت\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد بلوند روشن و قاب صورت\">↔نمونه تغییر 03<h3>بلوند روشن و قاب صورت</h3><p>مقایسه دو قاب هم‌زاویه از نتیجه رنگ و لایت.</p></article><article><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"قبل از طراحی ناخن و نتیجه نهایی\"><img loading=\"lazy\" decoding=\"async\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"بعد از طراحی ناخن و نتیجه نهایی\"><input type=\"range\" min=\"0\" max=\"100\" value=\"50\" aria-label=\"مقایسه قبل و بعد طراحی ناخن و نتیجه نهایی\">↔نمونه تغییر 04<h3>طراحی ناخن و نتیجه نهایی</h3><p>مقایسه نمای قبل و بعد از طراحی ناخن در یک قاب نزدیک و هماهنگ.</p></article></section>				\n					<section><header><h2>نتیجه‌ها در حرکت</h2></header><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"میکاپ دولوبیوتیا در نمای نزدیک، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-hair.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی میکاپ دولوبیوتیا در نمای نزدیک\">▶</button><small>ریل میکاپ</small><h3>میکاپ دولوبیوتیا در نمای نزدیک</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"اجرای تمیز و جزئیات دقیق، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-nails.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی اجرای تمیز و جزئیات دقیق\">▶</button><small>ریل میکاپ</small><h3>اجرای تمیز و جزئیات دقیق</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"موج‌های براق و طبیعی، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-salon.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی موج‌های براق و طبیعی\">▶</button><small>ریل رنگ و مو</small><h3>موج‌های براق و طبیعی</h3><button type=\"button\">پخش ویدیو ▶</button></article><article><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"فینیش لایت و پوست شفاف، کاور ویدیو\"><video data-auto-poster=\"1\" preload=\"none\" playsinline controls poster=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" data-src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-reel-makeup.mp4\"></video><button type=\"button\" aria-label=\"پخش ویدیوی فینیش لایت و پوست شفاف\">▶</button><small>ریل رنگ و مو</small><h3>فینیش لایت و پوست شفاف</h3><button type=\"button\">پخش ویدیو ▶</button></article></section>				\n					<section id=\"booking\"><h2>BOOK NOW</h2>۱<strong>انتخاب خدمت</strong><small>خدمت و متخصص</small>۲<strong>انتخاب مدل</strong><small>از نمونه‌کارهای دولوبیوتیا</small>۳<strong>انتخاب زمان</strong><small>روز و ساعت آزاد</small>۴<strong>تأیید نهایی</strong><small>ارسال وضعیت با پیامک</small><button type=\"button\">همین حالا رزرو کن</button></section>				\n					<section><h2>تازه‌ترین از زیبایی‌نامه</h2><a href=\"http://localhost/develobeautia/beauty-journal/\">همه مقاله‌ها ←</a><article><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hero.png\" alt=\"راهنمای مراقبت از ناخن بعد از ژل و لمینت\"></a><small>2 اکتبر 2026</small><h3><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">راهنمای مراقبت از ناخن بعد از ژل و لمینت</a></h3><p>نتیجه خوب خدمات ناخن فقط به اجرای روز اول وابسته نیست؛ مراقبت چند روز اول و عادت‌های ساده روزانه نقش مهمی در دوام، سلامت&hellip;</p><a href=\"http://localhost/develobeautia/nail-gel-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/makeup-preparation/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-makeup.png\" alt=\"راهنمای آماده‌شدن برای میکاپ مراسم\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/makeup-preparation/\">راهنمای آماده‌شدن برای میکاپ مراسم</a></h3><p>میکاپ ماندگار از چند روز قبل از مراسم شروع می‌شود. پوست آرام و آبرسانی‌شده، انتخاب مدل واقع‌بینانه و برنامه‌ریزی درست، نتیجه را تمیزتر و&hellip;</p><a href=\"http://localhost/develobeautia/makeup-preparation/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/balayage-aftercare/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-hair.png\" alt=\"مراقبت بعد از بالیاژ\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مراقبت بعد از بالیاژ</a></h3><p>بالیاژ خوب فقط به اجرای روز اول وابسته نیست؛ کیفیت مراقبت خانگی تعیین می‌کند درخشش تناژ و سلامت ساقه تا چه مدت باقی بماند.&hellip;</p><a href=\"http://localhost/develobeautia/balayage-aftercare/\">مطالعه مقاله ←</a></article><article><a href=\"http://localhost/develobeautia/hair-color-tone/\"><img loading=\"lazy\" src=\"http://localhost/develobeautia/wp-content/uploads/2026/10/develobeautia-nails.png\" alt=\"چطور تناژ مناسب پوستمان را انتخاب کنیم؟\"></a><small>21 سپتامبر 2026</small><h3><a href=\"http://localhost/develobeautia/hair-color-tone/\">چطور تناژ مناسب پوستمان را انتخاب کنیم؟</a></h3><p>رنگ مویی که روی یک نفر خیره‌کننده است، لزوماً روی دیگری همان نتیجه را نمی‌دهد. هماهنگی تناژ مو با ته‌رنگ پوست، رنگ چشم و&hellip;</p><a href=\"http://localhost/develobeautia/hair-color-tone/\">مطالعه مقاله ←</a></article></section>				\n					<section><h2>تماس با دولوبیوتیا</h2><p>منتظر دیدنت هستیم</p>آدرس سالن<p>شهر شما، نشانی سالن شما</p><a href=\"https://maps.google.com/?q=%D8%AA%D9%87%D8%B1%D8%A7%D9%86%D8%8C%20%D9%81%D8%B1%D8%B4%D8%AA%D9%87%D8%8C%20%D9%85%D8%AC%D8%AA%D9%85%D8%B9%20%D8%AA%D8%AC%D8%A7%D8%B1%DB%8C%20%D8%AF%D8%A7%D8%B1%DB%8C%D9%88%D8%B4%D8%8C%20%D8%A8%D9%84%D9%88%DA%A9%20B%D8%8C%20%D8%B7%D8%A8%D9%82%D9%87%20%DB%B3%D8%8C%20%D9%88%D8%A7%D8%AD%D8%AF%20%DB%B2%DB%B3%DB%B8\" target=\"_blank\" rel=\"noopener\">نمایش روی نقشه ↗</a><a href=\"tel:02100000000\"><small>تلفن سالن</small><strong>02100000000</strong></a><a href=\"tel:09000000000\"><small>رزرو و مشاوره</small><strong>09000000000</strong></a><a href=\"#\" target=\"_blank\" rel=\"noopener\"><small>اینستاگرام</small><strong>صفحه رسمی دولوبیوتیا ↗</strong></a><button type=\"button\">رزرو نوبت</button></section>', 'صفحه اصلی', 'مرکز زیبایی دولوبیوتیا در شهر شما؛ رنگ و لایت، میکاپ، ناخن، مو و ابرو با مشاوره اختصاصی و رزرو مرحله‌ای.', 'inherit', 'closed', 'closed', '', '100-revision-v1', '', '', '2026-10-04 02:53:19', '2026-10-03 23:23:19', '', 100, 'http://localhost/develobeautia/?p=353', 0, 'revision', '', 0),
